INSERT INTO "ayahs" VALUES(5016,56,37,'عُرُبًا أَتْرَابًا',535,27,54,214,2,7,469,0);
INSERT INTO "ayahs" VALUES(5017,56,38,'لِّأَصْحَـٰبِ ٱلْيَمِينِ',535,27,54,214,2,7,469,0);
INSERT INTO "ayahs" VALUES(5018,56,39,'ثُلَّةٌ مِّنَ ٱلْأَوَّلِينَ',535,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5019,56,40,'وَثُلَّةٌ مِّنَ ٱلْـَٔاخِرِينَ',535,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5020,56,41,'وَأَصْحَـٰبُ ٱلشِّمَالِ مَآ أَصْحَـٰبُ ٱلشِّمَالِ',535,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5021,56,42,'فِى سَمُومٍ وَحَمِيمٍ',535,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5022,56,43,'وَظِلٍّ مِّن يَحْمُومٍ',535,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5023,56,44,'لَّا بَارِدٍ وَلَا كَرِيمٍ',535,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5024,56,45,'إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُتْرَفِينَ',535,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5025,56,46,'وَكَانُوا۟ يُصِرُّونَ عَلَى ٱلْحِنثِ ٱلْعَظِيمِ',535,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5026,56,47,'وَكَانُوا۟ يَقُولُونَ أَئِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَـٰمًا أَءِنَّا لَمَبْعُوثُونَ',535,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5027,56,48,'أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ',535,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5028,56,49,'قُلْ إِنَّ ٱلْأَوَّلِينَ وَٱلْـَٔاخِرِينَ',535,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5029,56,50,'لَمَجْمُوعُونَ إِلَىٰ مِيقَـٰتِ يَوْمٍ مَّعْلُومٍ',535,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5030,56,51,'ثُمَّ إِنَّكُمْ أَيُّهَا ٱلضَّآلُّونَ ٱلْمُكَذِّبُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5031,56,52,'لَـَٔاكِلُونَ مِن شَجَرٍ مِّن زَقُّومٍ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5032,56,53,'فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5033,56,54,'فَشَـٰرِبُونَ عَلَيْهِ مِنَ ٱلْحَمِيمِ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5034,56,55,'فَشَـٰرِبُونَ شُرْبَ ٱلْهِيمِ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5035,56,56,'هَـٰذَا نُزُلُهُمْ يَوْمَ ٱلدِّينِ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5036,56,57,'نَحْنُ خَلَقْنَـٰكُمْ فَلَوْلَا تُصَدِّقُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5037,56,58,'أَفَرَءَيْتُم مَّا تُمْنُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5038,56,59,'ءَأَنتُمْ تَخْلُقُونَهُۥٓ أَمْ نَحْنُ ٱلْخَـٰلِقُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5039,56,60,'نَحْنُ قَدَّرْنَا بَيْنَكُمُ ٱلْمَوْتَ وَمَا نَحْنُ بِمَسْبُوقِينَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5040,56,61,'عَلَىٰٓ أَن نُّبَدِّلَ أَمْثَـٰلَكُمْ وَنُنشِئَكُمْ فِى مَا لَا تَعْلَمُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5041,56,62,'وَلَقَدْ عَلِمْتُمُ ٱلنَّشْأَةَ ٱلْأُولَىٰ فَلَوْلَا تَذَكَّرُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5042,56,63,'أَفَرَءَيْتُم مَّا تَحْرُثُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5043,56,64,'ءَأَنتُمْ تَزْرَعُونَهُۥٓ أَمْ نَحْنُ ٱلزَّٰرِعُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5044,56,65,'لَوْ نَشَآءُ لَجَعَلْنَـٰهُ حُطَـٰمًا فَظَلْتُمْ تَفَكَّهُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5045,56,66,'إِنَّا لَمُغْرَمُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5046,56,67,'بَلْ نَحْنُ مَحْرُومُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5047,56,68,'أَفَرَءَيْتُمُ ٱلْمَآءَ ٱلَّذِى تَشْرَبُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5048,56,69,'ءَأَنتُمْ أَنزَلْتُمُوهُ مِنَ ٱلْمُزْنِ أَمْ نَحْنُ ٱلْمُنزِلُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5049,56,70,'لَوْ نَشَآءُ جَعَلْنَـٰهُ أُجَاجًا فَلَوْلَا تَشْكُرُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5050,56,71,'أَفَرَءَيْتُمُ ٱلنَّارَ ٱلَّتِى تُورُونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5051,56,72,'ءَأَنتُمْ أَنشَأْتُمْ شَجَرَتَهَآ أَمْ نَحْنُ ٱلْمُنشِـُٔونَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5052,56,73,'نَحْنُ جَعَلْنَـٰهَا تَذْكِرَةً وَمَتَـٰعًا لِّلْمُقْوِينَ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5053,56,74,'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ',536,27,54,214,2,7,470,0);
INSERT INTO "ayahs" VALUES(5054,56,75,'۞ فَلَآ أُقْسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ',536,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5055,56,76,'وَإِنَّهُۥ لَقَسَمٌ لَّوْ تَعْلَمُونَ عَظِيمٌ',536,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5056,56,77,'إِنَّهُۥ لَقُرْءَانٌ كَرِيمٌ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5057,56,78,'فِى كِتَـٰبٍ مَّكْنُونٍ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5058,56,79,'لَّا يَمَسُّهُۥٓ إِلَّا ٱلْمُطَهَّرُونَ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5059,56,80,'تَنزِيلٌ مِّن رَّبِّ ٱلْعَـٰلَمِينَ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5060,56,81,'أَفَبِهَـٰذَا ٱلْحَدِيثِ أَنتُم مُّدْهِنُونَ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5061,56,82,'وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5062,56,83,'فَلَوْلَآ إِذَا بَلَغَتِ ٱلْحُلْقُومَ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5063,56,84,'وَأَنتُمْ حِينَئِذٍ تَنظُرُونَ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5064,56,85,'وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنكُمْ وَلَـٰكِن لَّا تُبْصِرُونَ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5065,56,86,'فَلَوْلَآ إِن كُنتُمْ غَيْرَ مَدِينِينَ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5066,56,87,'تَرْجِعُونَهَآ إِن كُنتُمْ صَـٰدِقِينَ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5067,56,88,'فَأَمَّآ إِن كَانَ مِنَ ٱلْمُقَرَّبِينَ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5068,56,89,'فَرَوْحٌ وَرَيْحَانٌ وَجَنَّتُ نَعِيمٍ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5069,56,90,'وَأَمَّآ إِن كَانَ مِنْ أَصْحَـٰبِ ٱلْيَمِينِ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5070,56,91,'فَسَلَـٰمٌ لَّكَ مِنْ أَصْحَـٰبِ ٱلْيَمِينِ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5071,56,92,'وَأَمَّآ إِن كَانَ مِنَ ٱلْمُكَذِّبِينَ ٱلضَّآلِّينَ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5072,56,93,'فَنُزُلٌ مِّنْ حَمِيمٍ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5073,56,94,'وَتَصْلِيَةُ جَحِيمٍ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5074,56,95,'إِنَّ هَـٰذَا لَهُوَ حَقُّ ٱلْيَقِينِ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5075,56,96,'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ',537,27,54,215,3,7,471,0);
INSERT INTO "ayahs" VALUES(5076,57,1,'سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ',537,27,54,215,3,7,472,0);
INSERT INTO "ayahs" VALUES(5077,57,2,'لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ يُحْىِۦ وَيُمِيتُ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ',537,27,54,215,3,7,472,0);
INSERT INTO "ayahs" VALUES(5078,57,3,'هُوَ ٱلْأَوَّلُ وَٱلْـَٔاخِرُ وَٱلظَّـٰهِرُ وَٱلْبَاطِنُ ۖ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ',537,27,54,215,3,7,472,0);
INSERT INTO "ayahs" VALUES(5079,57,4,'هُوَ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۚ يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا ۖ وَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ',538,27,54,215,3,7,472,0);
INSERT INTO "ayahs" VALUES(5080,57,5,'لَّهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ',538,27,54,215,3,7,472,0);
INSERT INTO "ayahs" VALUES(5081,57,6,'يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ ۚ وَهُوَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ',538,27,54,215,3,7,472,0);
INSERT INTO "ayahs" VALUES(5082,57,7,'ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُوا۟ مِمَّا جَعَلَكُم مُّسْتَخْلَفِينَ فِيهِ ۖ فَٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَأَنفَقُوا۟ لَهُمْ أَجْرٌ كَبِيرٌ',538,27,54,215,3,7,472,0);
INSERT INTO "ayahs" VALUES(5083,57,8,'وَمَا لَكُمْ لَا تُؤْمِنُونَ بِٱللَّهِ ۙ وَٱلرَّسُولُ يَدْعُوكُمْ لِتُؤْمِنُوا۟ بِرَبِّكُمْ وَقَدْ أَخَذَ مِيثَـٰقَكُمْ إِن كُنتُم مُّؤْمِنِينَ',538,27,54,215,3,7,472,0);
INSERT INTO "ayahs" VALUES(5084,57,9,'هُوَ ٱلَّذِى يُنَزِّلُ عَلَىٰ عَبْدِهِۦٓ ءَايَـٰتٍۭ بَيِّنَـٰتٍ لِّيُخْرِجَكُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ ۚ وَإِنَّ ٱللَّهَ بِكُمْ لَرَءُوفٌ رَّحِيمٌ',538,27,54,215,3,7,472,0);
INSERT INTO "ayahs" VALUES(5085,57,10,'وَمَا لَكُمْ أَلَّا تُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ لَا يَسْتَوِى مِنكُم مَّنْ أَنفَقَ مِن قَبْلِ ٱلْفَتْحِ وَقَـٰتَلَ ۚ أُو۟لَـٰٓئِكَ أَعْظَمُ دَرَجَةً مِّنَ ٱلَّذِينَ أَنفَقُوا۟ مِنۢ بَعْدُ وَقَـٰتَلُوا۟ ۚ وَكُلًّا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ',538,27,54,215,3,7,472,0);
INSERT INTO "ayahs" VALUES(5086,57,11,'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَـٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجْرٌ كَرِيمٌ',538,27,54,215,3,7,473,0);
INSERT INTO "ayahs" VALUES(5087,57,12,'يَوْمَ تَرَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ يَسْعَىٰ نُورُهُم بَيْنَ أَيْدِيهِمْ وَبِأَيْمَـٰنِهِم بُشْرَىٰكُمُ ٱلْيَوْمَ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ',539,27,54,215,3,7,473,0);
INSERT INTO "ayahs" VALUES(5088,57,13,'يَوْمَ يَقُولُ ٱلْمُنَـٰفِقُونَ وَٱلْمُنَـٰفِقَـٰتُ لِلَّذِينَ ءَامَنُوا۟ ٱنظُرُونَا نَقْتَبِسْ مِن نُّورِكُمْ قِيلَ ٱرْجِعُوا۟ وَرَآءَكُمْ فَٱلْتَمِسُوا۟ نُورًا فَضُرِبَ بَيْنَهُم بِسُورٍ لَّهُۥ بَابٌۢ بَاطِنُهُۥ فِيهِ ٱلرَّحْمَةُ وَظَـٰهِرُهُۥ مِن قِبَلِهِ ٱلْعَذَابُ',539,27,54,215,3,7,473,0);
INSERT INTO "ayahs" VALUES(5089,57,14,'يُنَادُونَهُمْ أَلَمْ نَكُن مَّعَكُمْ ۖ قَالُوا۟ بَلَىٰ وَلَـٰكِنَّكُمْ فَتَنتُمْ أَنفُسَكُمْ وَتَرَبَّصْتُمْ وَٱرْتَبْتُمْ وَغَرَّتْكُمُ ٱلْأَمَانِىُّ حَتَّىٰ جَآءَ أَمْرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلْغَرُورُ',539,27,54,215,3,7,473,0);
INSERT INTO "ayahs" VALUES(5090,57,15,'فَٱلْيَوْمَ لَا يُؤْخَذُ مِنكُمْ فِدْيَةٌ وَلَا مِنَ ٱلَّذِينَ كَفَرُوا۟ ۚ مَأْوَىٰكُمُ ٱلنَّارُ ۖ هِىَ مَوْلَىٰكُمْ ۖ وَبِئْسَ ٱلْمَصِيرُ',539,27,54,215,3,7,473,0);
INSERT INTO "ayahs" VALUES(5091,57,16,'۞ أَلَمْ يَأْنِ لِلَّذِينَ ءَامَنُوٓا۟ أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلْحَقِّ وَلَا يَكُونُوا۟ كَٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلُ فَطَالَ عَلَيْهِمُ ٱلْأَمَدُ فَقَسَتْ قُلُوبُهُمْ ۖ وَكَثِيرٌ مِّنْهُمْ فَـٰسِقُونَ',539,27,54,216,4,7,473,0);
INSERT INTO "ayahs" VALUES(5092,57,17,'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا ۚ قَدْ بَيَّنَّا لَكُمُ ٱلْـَٔايَـٰتِ لَعَلَّكُمْ تَعْقِلُونَ',539,27,54,216,4,7,473,0);
INSERT INTO "ayahs" VALUES(5093,57,18,'إِنَّ ٱلْمُصَّدِّقِينَ وَٱلْمُصَّدِّقَـٰتِ وَأَقْرَضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَـٰعَفُ لَهُمْ وَلَهُمْ أَجْرٌ كَرِيمٌ',539,27,54,216,4,7,473,0);
INSERT INTO "ayahs" VALUES(5094,57,19,'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦٓ أُو۟لَـٰٓئِكَ هُمُ ٱلصِّدِّيقُونَ ۖ وَٱلشُّهَدَآءُ عِندَ رَبِّهِمْ لَهُمْ أَجْرُهُمْ وَنُورُهُمْ ۖ وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَحِيمِ',540,27,54,216,4,7,473,0);
INSERT INTO "ayahs" VALUES(5095,57,20,'ٱعْلَمُوٓا۟ أَنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌ وَلَهْوٌ وَزِينَةٌ وَتَفَاخُرٌۢ بَيْنَكُمْ وَتَكَاثُرٌ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَـٰدِ ۖ كَمَثَلِ غَيْثٍ أَعْجَبَ ٱلْكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّا ثُمَّ يَكُونُ حُطَـٰمًا ۖ وَفِى ٱلْـَٔاخِرَةِ عَذَابٌ شَدِيدٌ وَمَغْفِرَةٌ مِّنَ ٱللَّهِ وَرِضْوَٰنٌ ۚ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَـٰعُ ٱلْغُرُورِ',540,27,54,216,4,7,474,0);
INSERT INTO "ayahs" VALUES(5096,57,21,'سَابِقُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ ٱلسَّمَآءِ وَٱلْأَرْضِ أُعِدَّتْ لِلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۚ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ',540,27,54,216,4,7,474,0);
INSERT INTO "ayahs" VALUES(5097,57,22,'مَآ أَصَابَ مِن مُّصِيبَةٍ فِى ٱلْأَرْضِ وَلَا فِىٓ أَنفُسِكُمْ إِلَّا فِى كِتَـٰبٍ مِّن قَبْلِ أَن نَّبْرَأَهَآ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ',540,27,54,216,4,7,474,0);
INSERT INTO "ayahs" VALUES(5098,57,23,'لِّكَيْلَا تَأْسَوْا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا۟ بِمَآ ءَاتَىٰكُمْ ۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ',540,27,54,216,4,7,474,0);
INSERT INTO "ayahs" VALUES(5099,57,24,'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ ۗ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ',540,27,54,216,4,7,474,0);
INSERT INTO "ayahs" VALUES(5100,57,25,'لَقَدْ أَرْسَلْنَا رُسُلَنَا بِٱلْبَيِّنَـٰتِ وَأَنزَلْنَا مَعَهُمُ ٱلْكِتَـٰبَ وَٱلْمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلْقِسْطِ ۖ وَأَنزَلْنَا ٱلْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ وَمَنَـٰفِعُ لِلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلْغَيْبِ ۚ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ',541,27,54,216,4,7,474,0);
INSERT INTO "ayahs" VALUES(5101,57,26,'وَلَقَدْ أَرْسَلْنَا نُوحًا وَإِبْرَٰهِيمَ وَجَعَلْنَا فِى ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلْكِتَـٰبَ ۖ فَمِنْهُم مُّهْتَدٍ ۖ وَكَثِيرٌ مِّنْهُمْ فَـٰسِقُونَ',541,27,54,216,4,7,475,0);
INSERT INTO "ayahs" VALUES(5102,57,27,'ثُمَّ قَفَّيْنَا عَلَىٰٓ ءَاثَـٰرِهِم بِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى ٱبْنِ مَرْيَمَ وَءَاتَيْنَـٰهُ ٱلْإِنجِيلَ وَجَعَلْنَا فِى قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأْفَةً وَرَحْمَةً وَرَهْبَانِيَّةً ٱبْتَدَعُوهَا مَا كَتَبْنَـٰهَا عَلَيْهِمْ إِلَّا ٱبْتِغَآءَ رِضْوَٰنِ ٱللَّهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا ۖ فَـَٔاتَيْنَا ٱلَّذِينَ ءَامَنُوا۟ مِنْهُمْ أَجْرَهُمْ ۖ وَكَثِيرٌ مِّنْهُمْ فَـٰسِقُونَ',541,27,54,216,4,7,475,0);
INSERT INTO "ayahs" VALUES(5103,57,28,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَءَامِنُوا۟ بِرَسُولِهِۦ يُؤْتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِۦ وَيَجْعَل لَّكُمْ نُورًا تَمْشُونَ بِهِۦ وَيَغْفِرْ لَكُمْ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ',541,27,54,216,4,7,475,0);
INSERT INTO "ayahs" VALUES(5104,57,29,'لِّئَلَّا يَعْلَمَ أَهْلُ ٱلْكِتَـٰبِ أَلَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّن فَضْلِ ٱللَّهِ ۙ وَأَنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ',541,27,54,216,4,7,475,0);
INSERT INTO "ayahs" VALUES(5105,58,1,'قَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّتِى تُجَـٰدِلُكَ فِى زَوْجِهَا وَتَشْتَكِىٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسْمَعُ تَحَاوُرَكُمَآ ۚ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ',542,28,55,217,1,7,476,0);
INSERT INTO "ayahs" VALUES(5106,58,2,'ٱلَّذِينَ يُظَـٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَـٰتِهِمْ ۖ إِنْ أُمَّهَـٰتُهُمْ إِلَّا ٱلَّـٰٓـِٔى وَلَدْنَهُمْ ۚ وَإِنَّهُمْ لَيَقُولُونَ مُنكَرًا مِّنَ ٱلْقَوْلِ وَزُورًا ۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌ',542,28,55,217,1,7,476,0);
INSERT INTO "ayahs" VALUES(5107,58,3,'وَٱلَّذِينَ يُظَـٰهِرُونَ مِن نِّسَآئِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا۟ فَتَحْرِيرُ رَقَبَةٍ مِّن قَبْلِ أَن يَتَمَآسَّا ۚ ذَٰلِكُمْ تُوعَظُونَ بِهِۦ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ',542,28,55,217,1,7,476,0);
INSERT INTO "ayahs" VALUES(5108,58,4,'فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِن قَبْلِ أَن يَتَمَآسَّا ۖ فَمَن لَّمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا ۚ ذَٰلِكَ لِتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ۚ وَتِلْكَ حُدُودُ ٱللَّهِ ۗ وَلِلْكَـٰفِرِينَ عَذَابٌ أَلِيمٌ',542,28,55,217,1,7,476,0);
INSERT INTO "ayahs" VALUES(5109,58,5,'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُوا۟ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ وَقَدْ أَنزَلْنَآ ءَايَـٰتٍۭ بَيِّنَـٰتٍ ۚ وَلِلْكَـٰفِرِينَ عَذَابٌ مُّهِينٌ',542,28,55,217,1,7,476,0);
INSERT INTO "ayahs" VALUES(5110,58,6,'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيُنَبِّئُهُم بِمَا عَمِلُوٓا۟ ۚ أَحْصَىٰهُ ٱللَّهُ وَنَسُوهُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ',542,28,55,217,1,7,476,0);
INSERT INTO "ayahs" VALUES(5111,58,7,'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ مَا يَكُونُ مِن نَّجْوَىٰ ثَلَـٰثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ وَلَآ أَدْنَىٰ مِن ذَٰلِكَ وَلَآ أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُوا۟ ۖ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُوا۟ يَوْمَ ٱلْقِيَـٰمَةِ ۚ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ',543,28,55,217,1,7,477,0);
INSERT INTO "ayahs" VALUES(5112,58,8,'أَلَمْ تَرَ إِلَى ٱلَّذِينَ نُهُوا۟ عَنِ ٱلنَّجْوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُوا۟ عَنْهُ وَيَتَنَـٰجَوْنَ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَإِذَا جَآءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ ٱللَّهُ وَيَقُولُونَ فِىٓ أَنفُسِهِمْ لَوْلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُ ۚ حَسْبُهُمْ جَهَنَّمُ يَصْلَوْنَهَا ۖ فَبِئْسَ ٱلْمَصِيرُ',543,28,55,217,1,7,477,0);
INSERT INTO "ayahs" VALUES(5113,58,9,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَنَـٰجَيْتُمْ فَلَا تَتَنَـٰجَوْا۟ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَتَنَـٰجَوْا۟ بِٱلْبِرِّ وَٱلتَّقْوَىٰ ۖ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ',543,28,55,217,1,7,477,0);
INSERT INTO "ayahs" VALUES(5114,58,10,'إِنَّمَا ٱلنَّجْوَىٰ مِنَ ٱلشَّيْطَـٰنِ لِيَحْزُنَ ٱلَّذِينَ ءَامَنُوا۟ وَلَيْسَ بِضَآرِّهِمْ شَيْـًٔا إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ',543,28,55,217,1,7,477,0);
INSERT INTO "ayahs" VALUES(5115,58,11,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قِيلَ لَكُمْ تَفَسَّحُوا۟ فِى ٱلْمَجَـٰلِسِ فَٱفْسَحُوا۟ يَفْسَحِ ٱللَّهُ لَكُمْ ۖ وَإِذَا قِيلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَـٰتٍ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ',543,28,55,217,1,7,477,0);
INSERT INTO "ayahs" VALUES(5116,58,12,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَـٰجَيْتُمُ ٱلرَّسُولَ فَقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَةً ۚ ذَٰلِكَ خَيْرٌ لَّكُمْ وَأَطْهَرُ ۚ فَإِن لَّمْ تَجِدُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ',544,28,55,217,1,7,477,0);
INSERT INTO "ayahs" VALUES(5117,58,13,'ءَأَشْفَقْتُمْ أَن تُقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَـٰتٍ ۚ فَإِذْ لَمْ تَفْعَلُوا۟ وَتَابَ ٱللَّهُ عَلَيْكُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ',544,28,55,217,1,7,477,0);
INSERT INTO "ayahs" VALUES(5118,58,14,'۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِم مَّا هُم مِّنكُمْ وَلَا مِنْهُمْ وَيَحْلِفُونَ عَلَى ٱلْكَذِبِ وَهُمْ يَعْلَمُونَ',544,28,55,218,2,7,478,0);
INSERT INTO "ayahs" VALUES(5119,58,15,'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا ۖ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ',544,28,55,218,2,7,478,0);
INSERT INTO "ayahs" VALUES(5120,58,16,'ٱتَّخَذُوٓا۟ أَيْمَـٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ فَلَهُمْ عَذَابٌ مُّهِينٌ',544,28,55,218,2,7,478,0);
INSERT INTO "ayahs" VALUES(5121,58,17,'لَّن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَـٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا ۚ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ',544,28,55,218,2,7,478,0);
INSERT INTO "ayahs" VALUES(5122,58,18,'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيَحْلِفُونَ لَهُۥ كَمَا يَحْلِفُونَ لَكُمْ ۖ وَيَحْسَبُونَ أَنَّهُمْ عَلَىٰ شَىْءٍ ۚ أَلَآ إِنَّهُمْ هُمُ ٱلْكَـٰذِبُونَ',544,28,55,218,2,7,478,0);
INSERT INTO "ayahs" VALUES(5123,58,19,'ٱسْتَحْوَذَ عَلَيْهِمُ ٱلشَّيْطَـٰنُ فَأَنسَىٰهُمْ ذِكْرَ ٱللَّهِ ۚ أُو۟لَـٰٓئِكَ حِزْبُ ٱلشَّيْطَـٰنِ ۚ أَلَآ إِنَّ حِزْبَ ٱلشَّيْطَـٰنِ هُمُ ٱلْخَـٰسِرُونَ',544,28,55,218,2,7,478,0);
INSERT INTO "ayahs" VALUES(5124,58,20,'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَـٰٓئِكَ فِى ٱلْأَذَلِّينَ',544,28,55,218,2,7,478,0);
INSERT INTO "ayahs" VALUES(5125,58,21,'كَتَبَ ٱللَّهُ لَأَغْلِبَنَّ أَنَا۠ وَرُسُلِىٓ ۚ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ',544,28,55,218,2,7,478,0);
INSERT INTO "ayahs" VALUES(5126,58,22,'لَّا تَجِدُ قَوْمًا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ يُوَآدُّونَ مَنْ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوْ كَانُوٓا۟ ءَابَآءَهُمْ أَوْ أَبْنَآءَهُمْ أَوْ إِخْوَٰنَهُمْ أَوْ عَشِيرَتَهُمْ ۚ أُو۟لَـٰٓئِكَ كَتَبَ فِى قُلُوبِهِمُ ٱلْإِيمَـٰنَ وَأَيَّدَهُم بِرُوحٍ مِّنْهُ ۖ وَيُدْخِلُهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ رَضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ أُو۟لَـٰٓئِكَ حِزْبُ ٱللَّهِ ۚ أَلَآ إِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْمُفْلِحُونَ',545,28,55,218,2,7,478,0);
INSERT INTO "ayahs" VALUES(5127,59,1,'سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ',545,28,55,218,2,7,479,0);
INSERT INTO "ayahs" VALUES(5128,59,2,'هُوَ ٱلَّذِىٓ أَخْرَجَ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ مِن دِيَـٰرِهِمْ لِأَوَّلِ ٱلْحَشْرِ ۚ مَا ظَنَنتُمْ أَن يَخْرُجُوا۟ ۖ وَظَنُّوٓا۟ أَنَّهُم مَّانِعَتُهُمْ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا۟ ۖ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ ۚ يُخْرِبُونَ بُيُوتَهُم بِأَيْدِيهِمْ وَأَيْدِى ٱلْمُؤْمِنِينَ فَٱعْتَبِرُوا۟ يَـٰٓأُو۟لِى ٱلْأَبْصَـٰرِ',545,28,55,218,2,7,479,0);
INSERT INTO "ayahs" VALUES(5129,59,3,'وَلَوْلَآ أَن كَتَبَ ٱللَّهُ عَلَيْهِمُ ٱلْجَلَآءَ لَعَذَّبَهُمْ فِى ٱلدُّنْيَا ۖ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابُ ٱلنَّارِ',545,28,55,218,2,7,479,0);
INSERT INTO "ayahs" VALUES(5130,59,4,'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ ۖ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ',546,28,55,218,2,7,479,0);
INSERT INTO "ayahs" VALUES(5131,59,5,'مَا قَطَعْتُم مِّن لِّينَةٍ أَوْ تَرَكْتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذْنِ ٱللَّهِ وَلِيُخْزِىَ ٱلْفَـٰسِقِينَ',546,28,55,218,2,7,479,0);
INSERT INTO "ayahs" VALUES(5132,59,6,'وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْهُمْ فَمَآ أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ وَلَـٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ',546,28,55,218,2,7,479,0);
INSERT INTO "ayahs" VALUES(5133,59,7,'مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْ أَهْلِ ٱلْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَٱبْنِ ٱلسَّبِيلِ كَىْ لَا يَكُونَ دُولَةًۢ بَيْنَ ٱلْأَغْنِيَآءِ مِنكُمْ ۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمْ عَنْهُ فَٱنتَهُوا۟ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ',546,28,55,218,2,7,479,0);
INSERT INTO "ayahs" VALUES(5134,59,8,'لِلْفُقَرَآءِ ٱلْمُهَـٰجِرِينَ ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَـٰرِهِمْ وَأَمْوَٰلِهِمْ يَبْتَغُونَ فَضْلًا مِّنَ ٱللَّهِ وَرِضْوَٰنًا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلصَّـٰدِقُونَ',546,28,55,218,2,7,479,0);
INSERT INTO "ayahs" VALUES(5135,59,9,'وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلْإِيمَـٰنَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِى صُدُورِهِمْ حَاجَةً مِّمَّآ أُوتُوا۟ وَيُؤْثِرُونَ عَلَىٰٓ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ ۚ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ',546,28,55,218,2,7,479,0);
INSERT INTO "ayahs" VALUES(5136,59,10,'وَٱلَّذِينَ جَآءُو مِنۢ بَعْدِهِمْ يَقُولُونَ رَبَّنَا ٱغْفِرْ لَنَا وَلِإِخْوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلْإِيمَـٰنِ وَلَا تَجْعَلْ فِى قُلُوبِنَا غِلًّا لِّلَّذِينَ ءَامَنُوا۟ رَبَّنَآ إِنَّكَ رَءُوفٌ رَّحِيمٌ',547,28,55,218,2,7,479,0);
INSERT INTO "ayahs" VALUES(5137,59,11,'۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ نَافَقُوا۟ يَقُولُونَ لِإِخْوَٰنِهِمُ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيعُ فِيكُمْ أَحَدًا أَبَدًا وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَـٰذِبُونَ',547,28,55,219,3,7,480,0);
INSERT INTO "ayahs" VALUES(5138,59,12,'لَئِنْ أُخْرِجُوا۟ لَا يَخْرُجُونَ مَعَهُمْ وَلَئِن قُوتِلُوا۟ لَا يَنصُرُونَهُمْ وَلَئِن نَّصَرُوهُمْ لَيُوَلُّنَّ ٱلْأَدْبَـٰرَ ثُمَّ لَا يُنصَرُونَ',547,28,55,219,3,7,480,0);
INSERT INTO "ayahs" VALUES(5139,59,13,'لَأَنتُمْ أَشَدُّ رَهْبَةً فِى صُدُورِهِم مِّنَ ٱللَّهِ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ',547,28,55,219,3,7,480,0);
INSERT INTO "ayahs" VALUES(5140,59,14,'لَا يُقَـٰتِلُونَكُمْ جَمِيعًا إِلَّا فِى قُرًى مُّحَصَّنَةٍ أَوْ مِن وَرَآءِ جُدُرٍۭ ۚ بَأْسُهُم بَيْنَهُمْ شَدِيدٌ ۚ تَحْسَبُهُمْ جَمِيعًا وَقُلُوبُهُمْ شَتَّىٰ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ',547,28,55,219,3,7,480,0);
INSERT INTO "ayahs" VALUES(5141,59,15,'كَمَثَلِ ٱلَّذِينَ مِن قَبْلِهِمْ قَرِيبًا ۖ ذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ',547,28,55,219,3,7,480,0);
INSERT INTO "ayahs" VALUES(5142,59,16,'كَمَثَلِ ٱلشَّيْطَـٰنِ إِذْ قَالَ لِلْإِنسَـٰنِ ٱكْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّى بَرِىٓءٌ مِّنكَ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَـٰلَمِينَ',547,28,55,219,3,7,480,0);
INSERT INTO "ayahs" VALUES(5143,59,17,'فَكَانَ عَـٰقِبَتَهُمَآ أَنَّهُمَا فِى ٱلنَّارِ خَـٰلِدَيْنِ فِيهَا ۚ وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّـٰلِمِينَ',548,28,55,219,3,7,480,0);
INSERT INTO "ayahs" VALUES(5144,59,18,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَلْتَنظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ',548,28,55,219,3,7,481,0);
INSERT INTO "ayahs" VALUES(5145,59,19,'وَلَا تَكُونُوا۟ كَٱلَّذِينَ نَسُوا۟ ٱللَّهَ فَأَنسَىٰهُمْ أَنفُسَهُمْ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلْفَـٰسِقُونَ',548,28,55,219,3,7,481,0);
INSERT INTO "ayahs" VALUES(5146,59,20,'لَا يَسْتَوِىٓ أَصْحَـٰبُ ٱلنَّارِ وَأَصْحَـٰبُ ٱلْجَنَّةِ ۚ أَصْحَـٰبُ ٱلْجَنَّةِ هُمُ ٱلْفَآئِزُونَ',548,28,55,219,3,7,481,0);
INSERT INTO "ayahs" VALUES(5147,59,21,'لَوْ أَنزَلْنَا هَـٰذَا ٱلْقُرْءَانَ عَلَىٰ جَبَلٍ لَّرَأَيْتَهُۥ خَـٰشِعًا مُّتَصَدِّعًا مِّنْ خَشْيَةِ ٱللَّهِ ۚ وَتِلْكَ ٱلْأَمْثَـٰلُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ',548,28,55,219,3,7,481,0);
INSERT INTO "ayahs" VALUES(5148,59,22,'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَـٰهَ إِلَّا هُوَ ۖ عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ۖ هُوَ ٱلرَّحْمَـٰنُ ٱلرَّحِيمُ',548,28,55,219,3,7,481,0);
INSERT INTO "ayahs" VALUES(5149,59,23,'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَـٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَـٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ',548,28,55,219,3,7,481,0);
INSERT INTO "ayahs" VALUES(5150,59,24,'هُوَ ٱللَّهُ ٱلْخَـٰلِقُ ٱلْبَارِئُ ٱلْمُصَوِّرُ ۖ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ ۚ يُسَبِّحُ لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ',548,28,55,219,3,7,481,0);
INSERT INTO "ayahs" VALUES(5151,60,1,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ عَدُوِّى وَعَدُوَّكُمْ أَوْلِيَآءَ تُلْقُونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَقَدْ كَفَرُوا۟ بِمَا جَآءَكُم مِّنَ ٱلْحَقِّ يُخْرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمْ ۙ أَن تُؤْمِنُوا۟ بِٱللَّهِ رَبِّكُمْ إِن كُنتُمْ خَرَجْتُمْ جِهَـٰدًا فِى سَبِيلِى وَٱبْتِغَآءَ مَرْضَاتِى ۚ تُسِرُّونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَأَنَا۠ أَعْلَمُ بِمَآ أَخْفَيْتُمْ وَمَآ أَعْلَنتُمْ ۚ وَمَن يَفْعَلْهُ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ',549,28,55,219,3,7,482,0);
INSERT INTO "ayahs" VALUES(5152,60,2,'إِن يَثْقَفُوكُمْ يَكُونُوا۟ لَكُمْ أَعْدَآءً وَيَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ وَأَلْسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّوا۟ لَوْ تَكْفُرُونَ',549,28,55,219,3,7,482,0);
INSERT INTO "ayahs" VALUES(5153,60,3,'لَن تَنفَعَكُمْ أَرْحَامُكُمْ وَلَآ أَوْلَـٰدُكُمْ ۚ يَوْمَ ٱلْقِيَـٰمَةِ يَفْصِلُ بَيْنَكُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ',549,28,55,219,3,7,482,0);
INSERT INTO "ayahs" VALUES(5154,60,4,'قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِىٓ إِبْرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذْ قَالُوا۟ لِقَوْمِهِمْ إِنَّا بُرَءَٰٓؤُا۟ مِنكُمْ وَمِمَّا تَعْبُدُونَ مِن دُونِ ٱللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ ٱلْعَدَٰوَةُ وَٱلْبَغْضَآءُ أَبَدًا حَتَّىٰ تُؤْمِنُوا۟ بِٱللَّهِ وَحْدَهُۥٓ إِلَّا قَوْلَ إِبْرَٰهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ وَمَآ أَمْلِكُ لَكَ مِنَ ٱللَّهِ مِن شَىْءٍ ۖ رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ ٱلْمَصِيرُ',549,28,55,219,3,7,482,0);
INSERT INTO "ayahs" VALUES(5155,60,5,'رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا۟ وَٱغْفِرْ لَنَا رَبَّنَآ ۖ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ',549,28,55,219,3,7,482,0);
INSERT INTO "ayahs" VALUES(5156,60,6,'لَقَدْ كَانَ لَكُمْ فِيهِمْ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْـَٔاخِرَ ۚ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ',550,28,55,219,3,7,482,0);
INSERT INTO "ayahs" VALUES(5157,60,7,'۞ عَسَى ٱللَّهُ أَن يَجْعَلَ بَيْنَكُمْ وَبَيْنَ ٱلَّذِينَ عَادَيْتُم مِّنْهُم مَّوَدَّةً ۚ وَٱللَّهُ قَدِيرٌ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ',550,28,55,220,4,7,483,0);
INSERT INTO "ayahs" VALUES(5158,60,8,'لَّا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمْ يُقَـٰتِلُوكُمْ فِى ٱلدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيَـٰرِكُمْ أَن تَبَرُّوهُمْ وَتُقْسِطُوٓا۟ إِلَيْهِمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ',550,28,55,220,4,7,483,0);
INSERT INTO "ayahs" VALUES(5159,60,9,'إِنَّمَا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَـٰتَلُوكُمْ فِى ٱلدِّينِ وَأَخْرَجُوكُم مِّن دِيَـٰرِكُمْ وَظَـٰهَرُوا۟ عَلَىٰٓ إِخْرَاجِكُمْ أَن تَوَلَّوْهُمْ ۚ وَمَن يَتَوَلَّهُمْ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ',550,28,55,220,4,7,483,0);
INSERT INTO "ayahs" VALUES(5160,60,10,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا جَآءَكُمُ ٱلْمُؤْمِنَـٰتُ مُهَـٰجِرَٰتٍ فَٱمْتَحِنُوهُنَّ ۖ ٱللَّهُ أَعْلَمُ بِإِيمَـٰنِهِنَّ ۖ فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِنَـٰتٍ فَلَا تَرْجِعُوهُنَّ إِلَى ٱلْكُفَّارِ ۖ لَا هُنَّ حِلٌّ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ ۖ وَءَاتُوهُم مَّآ أَنفَقُوا۟ ۚ وَلَا جُنَاحَ عَلَيْكُمْ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ ۚ وَلَا تُمْسِكُوا۟ بِعِصَمِ ٱلْكَوَافِرِ وَسْـَٔلُوا۟ مَآ أَنفَقْتُمْ وَلْيَسْـَٔلُوا۟ مَآ أَنفَقُوا۟ ۚ ذَٰلِكُمْ حُكْمُ ٱللَّهِ ۖ يَحْكُمُ بَيْنَكُمْ ۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ',550,28,55,220,4,7,483,0);
INSERT INTO "ayahs" VALUES(5161,60,11,'وَإِن فَاتَكُمْ شَىْءٌ مِّنْ أَزْوَٰجِكُمْ إِلَى ٱلْكُفَّارِ فَعَاقَبْتُمْ فَـَٔاتُوا۟ ٱلَّذِينَ ذَهَبَتْ أَزْوَٰجُهُم مِّثْلَ مَآ أَنفَقُوا۟ ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ',550,28,55,220,4,7,483,0);
INSERT INTO "ayahs" VALUES(5162,60,12,'يَـٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا جَآءَكَ ٱلْمُؤْمِنَـٰتُ يُبَايِعْنَكَ عَلَىٰٓ أَن لَّا يُشْرِكْنَ بِٱللَّهِ شَيْـًٔا وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَـٰدَهُنَّ وَلَا يَأْتِينَ بِبُهْتَـٰنٍ يَفْتَرِينَهُۥ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِينَكَ فِى مَعْرُوفٍ ۙ فَبَايِعْهُنَّ وَٱسْتَغْفِرْ لَهُنَّ ٱللَّهَ ۖ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ',551,28,55,220,4,7,483,0);
INSERT INTO "ayahs" VALUES(5163,60,13,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِمْ قَدْ يَئِسُوا۟ مِنَ ٱلْـَٔاخِرَةِ كَمَا يَئِسَ ٱلْكُفَّارُ مِنْ أَصْحَـٰبِ ٱلْقُبُورِ',551,28,55,220,4,7,483,0);
INSERT INTO "ayahs" VALUES(5164,61,1,'سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ',551,28,55,220,4,7,484,0);
INSERT INTO "ayahs" VALUES(5165,61,2,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ',551,28,55,220,4,7,484,0);
INSERT INTO "ayahs" VALUES(5166,61,3,'كَبُرَ مَقْتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفْعَلُونَ',551,28,55,220,4,7,484,0);
INSERT INTO "ayahs" VALUES(5167,61,4,'إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَـٰتِلُونَ فِى سَبِيلِهِۦ صَفًّا كَأَنَّهُم بُنْيَـٰنٌ مَّرْصُوصٌ',551,28,55,220,4,7,484,0);
INSERT INTO "ayahs" VALUES(5168,61,5,'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَـٰقَوْمِ لِمَ تُؤْذُونَنِى وَقَد تَّعْلَمُونَ أَنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ ۖ فَلَمَّا زَاغُوٓا۟ أَزَاغَ ٱللَّهُ قُلُوبَهُمْ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ',551,28,55,220,4,7,484,0);
INSERT INTO "ayahs" VALUES(5169,61,6,'وَإِذْ قَالَ عِيسَى ٱبْنُ مَرْيَمَ يَـٰبَنِىٓ إِسْرَٰٓءِيلَ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُم مُّصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَمُبَشِّرًۢا بِرَسُولٍ يَأْتِى مِنۢ بَعْدِى ٱسْمُهُۥٓ أَحْمَدُ ۖ فَلَمَّا جَآءَهُم بِٱلْبَيِّنَـٰتِ قَالُوا۟ هَـٰذَا سِحْرٌ مُّبِينٌ',552,28,55,220,4,7,484,0);
INSERT INTO "ayahs" VALUES(5170,61,7,'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُوَ يُدْعَىٰٓ إِلَى ٱلْإِسْلَـٰمِ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ',552,28,55,220,4,7,484,0);
INSERT INTO "ayahs" VALUES(5171,61,8,'يُرِيدُونَ لِيُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوْ كَرِهَ ٱلْكَـٰفِرُونَ',552,28,55,220,4,7,484,0);
INSERT INTO "ayahs" VALUES(5172,61,9,'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ',552,28,55,220,4,7,484,0);
INSERT INTO "ayahs" VALUES(5173,61,10,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ هَلْ أَدُلُّكُمْ عَلَىٰ تِجَـٰرَةٍ تُنجِيكُم مِّنْ عَذَابٍ أَلِيمٍ',552,28,55,220,4,7,485,0);
INSERT INTO "ayahs" VALUES(5174,61,11,'تُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَـٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ',552,28,55,220,4,7,485,0);
INSERT INTO "ayahs" VALUES(5175,61,12,'يَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَيُدْخِلْكُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ وَمَسَـٰكِنَ طَيِّبَةً فِى جَنَّـٰتِ عَدْنٍ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ',552,28,55,220,4,7,485,0);
INSERT INTO "ayahs" VALUES(5176,61,13,'وَأُخْرَىٰ تُحِبُّونَهَا ۖ نَصْرٌ مِّنَ ٱللَّهِ وَفَتْحٌ قَرِيبٌ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ',552,28,55,220,4,7,485,0);
INSERT INTO "ayahs" VALUES(5177,61,14,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوٓا۟ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِيسَى ٱبْنُ مَرْيَمَ لِلْحَوَارِيِّـۧنَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ ۖ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ۖ فَـَٔامَنَت طَّآئِفَةٌ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ وَكَفَرَت طَّآئِفَةٌ ۖ فَأَيَّدْنَا ٱلَّذِينَ ءَامَنُوا۟ عَلَىٰ عَدُوِّهِمْ فَأَصْبَحُوا۟ ظَـٰهِرِينَ',552,28,55,220,4,7,485,0);
INSERT INTO "ayahs" VALUES(5178,62,1,'يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ٱلْمَلِكِ ٱلْقُدُّوسِ ٱلْعَزِيزِ ٱلْحَكِيمِ',553,28,56,221,1,7,486,0);
INSERT INTO "ayahs" VALUES(5179,62,2,'هُوَ ٱلَّذِى بَعَثَ فِى ٱلْأُمِّيِّـۧنَ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَـٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَـٰلٍ مُّبِينٍ',553,28,56,221,1,7,486,0);
INSERT INTO "ayahs" VALUES(5180,62,3,'وَءَاخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا۟ بِهِمْ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ',553,28,56,221,1,7,486,0);
INSERT INTO "ayahs" VALUES(5181,62,4,'ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ',553,28,56,221,1,7,486,0);
INSERT INTO "ayahs" VALUES(5182,62,5,'مَثَلُ ٱلَّذِينَ حُمِّلُوا۟ ٱلتَّوْرَىٰةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ ٱلْحِمَارِ يَحْمِلُ أَسْفَارًۢا ۚ بِئْسَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِ ٱللَّهِ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ',553,28,56,221,1,7,486,0);
INSERT INTO "ayahs" VALUES(5183,62,6,'قُلْ يَـٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓا۟ إِن زَعَمْتُمْ أَنَّكُمْ أَوْلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَـٰدِقِينَ',553,28,56,221,1,7,486,0);
INSERT INTO "ayahs" VALUES(5184,62,7,'وَلَا يَتَمَنَّوْنَهُۥٓ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ ۚ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّـٰلِمِينَ',553,28,56,221,1,7,486,0);
INSERT INTO "ayahs" VALUES(5185,62,8,'قُلْ إِنَّ ٱلْمَوْتَ ٱلَّذِى تَفِرُّونَ مِنْهُ فَإِنَّهُۥ مُلَـٰقِيكُمْ ۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ',553,28,56,221,1,7,486,0);
INSERT INTO "ayahs" VALUES(5186,62,9,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نُودِىَ لِلصَّلَوٰةِ مِن يَوْمِ ٱلْجُمُعَةِ فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ وَذَرُوا۟ ٱلْبَيْعَ ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ',554,28,56,221,1,7,487,0);
INSERT INTO "ayahs" VALUES(5187,62,10,'فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِى ٱلْأَرْضِ وَٱبْتَغُوا۟ مِن فَضْلِ ٱللَّهِ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ',554,28,56,221,1,7,487,0);
INSERT INTO "ayahs" VALUES(5188,62,11,'وَإِذَا رَأَوْا۟ تِجَـٰرَةً أَوْ لَهْوًا ٱنفَضُّوٓا۟ إِلَيْهَا وَتَرَكُوكَ قَآئِمًا ۚ قُلْ مَا عِندَ ٱللَّهِ خَيْرٌ مِّنَ ٱللَّهْوِ وَمِنَ ٱلتِّجَـٰرَةِ ۚ وَٱللَّهُ خَيْرُ ٱلرَّٰزِقِينَ',554,28,56,221,1,7,487,0);
INSERT INTO "ayahs" VALUES(5189,63,1,'إِذَا جَآءَكَ ٱلْمُنَـٰفِقُونَ قَالُوا۟ نَشْهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِ ۗ وَٱللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشْهَدُ إِنَّ ٱلْمُنَـٰفِقِينَ لَكَـٰذِبُونَ',554,28,56,221,1,7,488,0);
INSERT INTO "ayahs" VALUES(5190,63,2,'ٱتَّخَذُوٓا۟ أَيْمَـٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ۚ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ',554,28,56,221,1,7,488,0);
INSERT INTO "ayahs" VALUES(5191,63,3,'ذَٰلِكَ بِأَنَّهُمْ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ',554,28,56,221,1,7,488,0);
INSERT INTO "ayahs" VALUES(5192,63,4,'۞ وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ ۖ وَإِن يَقُولُوا۟ تَسْمَعْ لِقَوْلِهِمْ ۖ كَأَنَّهُمْ خُشُبٌ مُّسَنَّدَةٌ ۖ يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ ۚ هُمُ ٱلْعَدُوُّ فَٱحْذَرْهُمْ ۚ قَـٰتَلَهُمُ ٱللَّهُ ۖ أَنَّىٰ يُؤْفَكُونَ',554,28,56,222,2,7,488,0);
INSERT INTO "ayahs" VALUES(5193,63,5,'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ يَسْتَغْفِرْ لَكُمْ رَسُولُ ٱللَّهِ لَوَّوْا۟ رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ',555,28,56,222,2,7,488,0);
INSERT INTO "ayahs" VALUES(5194,63,6,'سَوَآءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَن يَغْفِرَ ٱللَّهُ لَهُمْ ۚ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ',555,28,56,222,2,7,488,0);
INSERT INTO "ayahs" VALUES(5195,63,7,'هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُوا۟ عَلَىٰ مَنْ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّوا۟ ۗ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَلَـٰكِنَّ ٱلْمُنَـٰفِقِينَ لَا يَفْقَهُونَ',555,28,56,222,2,7,488,0);
INSERT INTO "ayahs" VALUES(5196,63,8,'يَقُولُونَ لَئِن رَّجَعْنَآ إِلَى ٱلْمَدِينَةِ لَيُخْرِجَنَّ ٱلْأَعَزُّ مِنْهَا ٱلْأَذَلَّ ۚ وَلِلَّهِ ٱلْعِزَّةُ وَلِرَسُولِهِۦ وَلِلْمُؤْمِنِينَ وَلَـٰكِنَّ ٱلْمُنَـٰفِقِينَ لَا يَعْلَمُونَ',555,28,56,222,2,7,488,0);
INSERT INTO "ayahs" VALUES(5197,63,9,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُلْهِكُمْ أَمْوَٰلُكُمْ وَلَآ أَوْلَـٰدُكُمْ عَن ذِكْرِ ٱللَّهِ ۚ وَمَن يَفْعَلْ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ',555,28,56,222,2,7,489,0);
INSERT INTO "ayahs" VALUES(5198,63,10,'وَأَنفِقُوا۟ مِن مَّا رَزَقْنَـٰكُم مِّن قَبْلِ أَن يَأْتِىَ أَحَدَكُمُ ٱلْمَوْتُ فَيَقُولَ رَبِّ لَوْلَآ أَخَّرْتَنِىٓ إِلَىٰٓ أَجَلٍ قَرِيبٍ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّـٰلِحِينَ',555,28,56,222,2,7,489,0);
INSERT INTO "ayahs" VALUES(5199,63,11,'وَلَن يُؤَخِّرَ ٱللَّهُ نَفْسًا إِذَا جَآءَ أَجَلُهَا ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ',555,28,56,222,2,7,489,0);
INSERT INTO "ayahs" VALUES(5200,64,1,'يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ',556,28,56,222,2,7,490,0);
INSERT INTO "ayahs" VALUES(5201,64,2,'هُوَ ٱلَّذِى خَلَقَكُمْ فَمِنكُمْ كَافِرٌ وَمِنكُم مُّؤْمِنٌ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ',556,28,56,222,2,7,490,0);
INSERT INTO "ayahs" VALUES(5202,64,3,'خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ ۖ وَإِلَيْهِ ٱلْمَصِيرُ',556,28,56,222,2,7,490,0);
INSERT INTO "ayahs" VALUES(5203,64,4,'يَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ ۚ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ',556,28,56,222,2,7,490,0);
INSERT INTO "ayahs" VALUES(5204,64,5,'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ فَذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ',556,28,56,222,2,7,490,0);
INSERT INTO "ayahs" VALUES(5205,64,6,'ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ فَقَالُوٓا۟ أَبَشَرٌ يَهْدُونَنَا فَكَفَرُوا۟ وَتَوَلَّوا۟ ۚ وَّٱسْتَغْنَى ٱللَّهُ ۚ وَٱللَّهُ غَنِىٌّ حَمِيدٌ',556,28,56,222,2,7,490,0);
INSERT INTO "ayahs" VALUES(5206,64,7,'زَعَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَن لَّن يُبْعَثُوا۟ ۚ قُلْ بَلَىٰ وَرَبِّى لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ ۚ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ',556,28,56,222,2,7,490,0);
INSERT INTO "ayahs" VALUES(5207,64,8,'فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِىٓ أَنزَلْنَا ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ',556,28,56,222,2,7,490,0);
INSERT INTO "ayahs" VALUES(5208,64,9,'يَوْمَ يَجْمَعُكُمْ لِيَوْمِ ٱلْجَمْعِ ۖ ذَٰلِكَ يَوْمُ ٱلتَّغَابُنِ ۗ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَـٰلِحًا يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُدْخِلْهُ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ',556,28,56,222,2,7,490,0);
INSERT INTO "ayahs" VALUES(5209,64,10,'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ خَـٰلِدِينَ فِيهَا ۖ وَبِئْسَ ٱلْمَصِيرُ',557,28,56,222,2,7,490,0);
INSERT INTO "ayahs" VALUES(5210,64,11,'مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۗ وَمَن يُؤْمِنۢ بِٱللَّهِ يَهْدِ قَلْبَهُۥ ۚ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ',557,28,56,222,2,7,491,0);
INSERT INTO "ayahs" VALUES(5211,64,12,'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ ۚ فَإِن تَوَلَّيْتُمْ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَـٰغُ ٱلْمُبِينُ',557,28,56,222,2,7,491,0);
INSERT INTO "ayahs" VALUES(5212,64,13,'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ',557,28,56,222,2,7,491,0);
INSERT INTO "ayahs" VALUES(5213,64,14,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ مِنْ أَزْوَٰجِكُمْ وَأَوْلَـٰدِكُمْ عَدُوًّا لَّكُمْ فَٱحْذَرُوهُمْ ۚ وَإِن تَعْفُوا۟ وَتَصْفَحُوا۟ وَتَغْفِرُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ',557,28,56,222,2,7,491,0);
INSERT INTO "ayahs" VALUES(5214,64,15,'إِنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَـٰدُكُمْ فِتْنَةٌ ۚ وَٱللَّهُ عِندَهُۥٓ أَجْرٌ عَظِيمٌ',557,28,56,222,2,7,491,0);
INSERT INTO "ayahs" VALUES(5215,64,16,'فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسْتَطَعْتُمْ وَٱسْمَعُوا۟ وَأَطِيعُوا۟ وَأَنفِقُوا۟ خَيْرًا لِّأَنفُسِكُمْ ۗ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ',557,28,56,222,2,7,491,0);
INSERT INTO "ayahs" VALUES(5216,64,17,'إِن تُقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَـٰعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ ۚ وَٱللَّهُ شَكُورٌ حَلِيمٌ',557,28,56,222,2,7,491,0);
INSERT INTO "ayahs" VALUES(5217,64,18,'عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ٱلْعَزِيزُ ٱلْحَكِيمُ',557,28,56,222,2,7,491,0);
INSERT INTO "ayahs" VALUES(5218,65,1,'يَـٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ ۖ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمْ ۖ لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّآ أَن يَأْتِينَ بِفَـٰحِشَةٍ مُّبَيِّنَةٍ ۚ وَتِلْكَ حُدُودُ ٱللَّهِ ۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدْ ظَلَمَ نَفْسَهُۥ ۚ لَا تَدْرِى لَعَلَّ ٱللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًا',558,28,56,223,3,7,492,0);
INSERT INTO "ayahs" VALUES(5219,65,2,'فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ وَأَشْهِدُوا۟ ذَوَىْ عَدْلٍ مِّنكُمْ وَأَقِيمُوا۟ ٱلشَّهَـٰدَةَ لِلَّهِ ۚ ذَٰلِكُمْ يُوعَظُ بِهِۦ مَن كَانَ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۚ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مَخْرَجًا',558,28,56,223,3,7,492,0);
INSERT INTO "ayahs" VALUES(5220,65,3,'وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ ۚ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَهُوَ حَسْبُهُۥٓ ۚ إِنَّ ٱللَّهَ بَـٰلِغُ أَمْرِهِۦ ۚ قَدْ جَعَلَ ٱللَّهُ لِكُلِّ شَىْءٍ قَدْرًا',558,28,56,223,3,7,492,0);
INSERT INTO "ayahs" VALUES(5221,65,4,'وَٱلَّـٰٓـِٔى يَئِسْنَ مِنَ ٱلْمَحِيضِ مِن نِّسَآئِكُمْ إِنِ ٱرْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَـٰثَةُ أَشْهُرٍ وَٱلَّـٰٓـِٔى لَمْ يَحِضْنَ ۚ وَأُو۟لَـٰتُ ٱلْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ ۚ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مِنْ أَمْرِهِۦ يُسْرًا',558,28,56,223,3,7,492,0);
INSERT INTO "ayahs" VALUES(5222,65,5,'ذَٰلِكَ أَمْرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيْكُمْ ۚ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُعْظِمْ لَهُۥٓ أَجْرًا',558,28,56,223,3,7,492,0);
INSERT INTO "ayahs" VALUES(5223,65,6,'أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنتُم مِّن وُجْدِكُمْ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُوا۟ عَلَيْهِنَّ ۚ وَإِن كُنَّ أُو۟لَـٰتِ حَمْلٍ فَأَنفِقُوا۟ عَلَيْهِنَّ حَتَّىٰ يَضَعْنَ حَمْلَهُنَّ ۚ فَإِنْ أَرْضَعْنَ لَكُمْ فَـَٔاتُوهُنَّ أُجُورَهُنَّ ۖ وَأْتَمِرُوا۟ بَيْنَكُم بِمَعْرُوفٍ ۖ وَإِن تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُۥٓ أُخْرَىٰ',559,28,56,223,3,7,492,0);
INSERT INTO "ayahs" VALUES(5224,65,7,'لِيُنفِقْ ذُو سَعَةٍ مِّن سَعَتِهِۦ ۖ وَمَن قُدِرَ عَلَيْهِ رِزْقُهُۥ فَلْيُنفِقْ مِمَّآ ءَاتَىٰهُ ٱللَّهُ ۚ لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا مَآ ءَاتَىٰهَا ۚ سَيَجْعَلُ ٱللَّهُ بَعْدَ عُسْرٍ يُسْرًا',559,28,56,223,3,7,492,0);
INSERT INTO "ayahs" VALUES(5225,65,8,'وَكَأَيِّن مِّن قَرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبْنَـٰهَا حِسَابًا شَدِيدًا وَعَذَّبْنَـٰهَا عَذَابًا نُّكْرًا',559,28,56,223,3,7,493,0);
INSERT INTO "ayahs" VALUES(5226,65,9,'فَذَاقَتْ وَبَالَ أَمْرِهَا وَكَانَ عَـٰقِبَةُ أَمْرِهَا خُسْرًا',559,28,56,223,3,7,493,0);
INSERT INTO "ayahs" VALUES(5227,65,10,'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا ۖ فَٱتَّقُوا۟ ٱللَّهَ يَـٰٓأُو۟لِى ٱلْأَلْبَـٰبِ ٱلَّذِينَ ءَامَنُوا۟ ۚ قَدْ أَنزَلَ ٱللَّهُ إِلَيْكُمْ ذِكْرًا',559,28,56,223,3,7,493,0);
INSERT INTO "ayahs" VALUES(5228,65,11,'رَّسُولًا يَتْلُوا۟ عَلَيْكُمْ ءَايَـٰتِ ٱللَّهِ مُبَيِّنَـٰتٍ لِّيُخْرِجَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ ۚ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَـٰلِحًا يُدْخِلْهُ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۖ قَدْ أَحْسَنَ ٱللَّهُ لَهُۥ رِزْقًا',559,28,56,223,3,7,493,0);
INSERT INTO "ayahs" VALUES(5229,65,12,'ٱللَّهُ ٱلَّذِى خَلَقَ سَبْعَ سَمَـٰوَٰتٍ وَمِنَ ٱلْأَرْضِ مِثْلَهُنَّ يَتَنَزَّلُ ٱلْأَمْرُ بَيْنَهُنَّ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ وَأَنَّ ٱللَّهَ قَدْ أَحَاطَ بِكُلِّ شَىْءٍ عِلْمًۢا',559,28,56,223,3,7,493,0);
INSERT INTO "ayahs" VALUES(5230,66,1,'يَـٰٓأَيُّهَا ٱلنَّبِىُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَ ۖ تَبْتَغِى مَرْضَاتَ أَزْوَٰجِكَ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ',560,28,56,224,4,7,494,0);
INSERT INTO "ayahs" VALUES(5231,66,2,'قَدْ فَرَضَ ٱللَّهُ لَكُمْ تَحِلَّةَ أَيْمَـٰنِكُمْ ۚ وَٱللَّهُ مَوْلَىٰكُمْ ۖ وَهُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ',560,28,56,224,4,7,494,0);
INSERT INTO "ayahs" VALUES(5232,66,3,'وَإِذْ أَسَرَّ ٱلنَّبِىُّ إِلَىٰ بَعْضِ أَزْوَٰجِهِۦ حَدِيثًا فَلَمَّا نَبَّأَتْ بِهِۦ وَأَظْهَرَهُ ٱللَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُۥ وَأَعْرَضَ عَنۢ بَعْضٍ ۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتْ مَنْ أَنۢبَأَكَ هَـٰذَا ۖ قَالَ نَبَّأَنِىَ ٱلْعَلِيمُ ٱلْخَبِيرُ',560,28,56,224,4,7,494,0);
INSERT INTO "ayahs" VALUES(5233,66,4,'إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا ۖ وَإِن تَظَـٰهَرَا عَلَيْهِ فَإِنَّ ٱللَّهَ هُوَ مَوْلَىٰهُ وَجِبْرِيلُ وَصَـٰلِحُ ٱلْمُؤْمِنِينَ ۖ وَٱلْمَلَـٰٓئِكَةُ بَعْدَ ذَٰلِكَ ظَهِيرٌ',560,28,56,224,4,7,494,0);
INSERT INTO "ayahs" VALUES(5234,66,5,'عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُۥٓ أَزْوَٰجًا خَيْرًا مِّنكُنَّ مُسْلِمَـٰتٍ مُّؤْمِنَـٰتٍ قَـٰنِتَـٰتٍ تَـٰٓئِبَـٰتٍ عَـٰبِدَٰتٍ سَـٰٓئِحَـٰتٍ ثَيِّبَـٰتٍ وَأَبْكَارًا',560,28,56,224,4,7,494,0);
INSERT INTO "ayahs" VALUES(5235,66,6,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ عَلَيْهَا مَلَـٰٓئِكَةٌ غِلَاظٌ شِدَادٌ لَّا يَعْصُونَ ٱللَّهَ مَآ أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ',560,28,56,224,4,7,494,0);
INSERT INTO "ayahs" VALUES(5236,66,7,'يَـٰٓأَيُّهَا ٱلَّذِينَ كَفَرُوا۟ لَا تَعْتَذِرُوا۟ ٱلْيَوْمَ ۖ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ',560,28,56,224,4,7,494,0);
INSERT INTO "ayahs" VALUES(5237,66,8,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ تُوبُوٓا۟ إِلَى ٱللَّهِ تَوْبَةً نَّصُوحًا عَسَىٰ رَبُّكُمْ أَن يُكَفِّرَ عَنكُمْ سَيِّـَٔاتِكُمْ وَيُدْخِلَكُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ يَوْمَ لَا يُخْزِى ٱللَّهُ ٱلنَّبِىَّ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ ۖ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَـٰنِهِمْ يَقُولُونَ رَبَّنَآ أَتْمِمْ لَنَا نُورَنَا وَٱغْفِرْ لَنَآ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ',561,28,56,224,4,7,495,0);
INSERT INTO "ayahs" VALUES(5238,66,9,'يَـٰٓأَيُّهَا ٱلنَّبِىُّ جَـٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَـٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ ۚ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ',561,28,56,224,4,7,495,0);
INSERT INTO "ayahs" VALUES(5239,66,10,'ضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ كَفَرُوا۟ ٱمْرَأَتَ نُوحٍ وَٱمْرَأَتَ لُوطٍ ۖ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَـٰلِحَيْنِ فَخَانَتَاهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ ٱللَّهِ شَيْـًٔا وَقِيلَ ٱدْخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ',561,28,56,224,4,7,495,0);
INSERT INTO "ayahs" VALUES(5240,66,11,'وَضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ ءَامَنُوا۟ ٱمْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ٱبْنِ لِى عِندَكَ بَيْتًا فِى ٱلْجَنَّةِ وَنَجِّنِى مِن فِرْعَوْنَ وَعَمَلِهِۦ وَنَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ',561,28,56,224,4,7,495,0);
INSERT INTO "ayahs" VALUES(5241,66,12,'وَمَرْيَمَ ٱبْنَتَ عِمْرَٰنَ ٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَـٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتْ مِنَ ٱلْقَـٰنِتِينَ',561,28,56,224,4,7,495,0);
INSERT INTO "ayahs" VALUES(5242,67,1,'تَبَـٰرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ',562,29,57,225,1,7,496,0);
INSERT INTO "ayahs" VALUES(5243,67,2,'ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ',562,29,57,225,1,7,496,0);
INSERT INTO "ayahs" VALUES(5244,67,3,'ٱلَّذِى خَلَقَ سَبْعَ سَمَـٰوَٰتٍ طِبَاقًا ۖ مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَـٰنِ مِن تَفَـٰوُتٍ ۖ فَٱرْجِعِ ٱلْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍ',562,29,57,225,1,7,496,0);
INSERT INTO "ayahs" VALUES(5245,67,4,'ثُمَّ ٱرْجِعِ ٱلْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ ٱلْبَصَرُ خَاسِئًا وَهُوَ حَسِيرٌ',562,29,57,225,1,7,496,0);
INSERT INTO "ayahs" VALUES(5246,67,5,'وَلَقَدْ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَـٰبِيحَ وَجَعَلْنَـٰهَا رُجُومًا لِّلشَّيَـٰطِينِ ۖ وَأَعْتَدْنَا لَهُمْ عَذَابَ ٱلسَّعِيرِ',562,29,57,225,1,7,496,0);
INSERT INTO "ayahs" VALUES(5247,67,6,'وَلِلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ عَذَابُ جَهَنَّمَ ۖ وَبِئْسَ ٱلْمَصِيرُ',562,29,57,225,1,7,496,0);
INSERT INTO "ayahs" VALUES(5248,67,7,'إِذَآ أُلْقُوا۟ فِيهَا سَمِعُوا۟ لَهَا شَهِيقًا وَهِىَ تَفُورُ',562,29,57,225,1,7,496,0);
INSERT INTO "ayahs" VALUES(5249,67,8,'تَكَادُ تَمَيَّزُ مِنَ ٱلْغَيْظِ ۖ كُلَّمَآ أُلْقِىَ فِيهَا فَوْجٌ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ نَذِيرٌ',562,29,57,225,1,7,496,0);
INSERT INTO "ayahs" VALUES(5250,67,9,'قَالُوا۟ بَلَىٰ قَدْ جَآءَنَا نَذِيرٌ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ٱللَّهُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا فِى ضَلَـٰلٍ كَبِيرٍ',562,29,57,225,1,7,496,0);
INSERT INTO "ayahs" VALUES(5251,67,10,'وَقَالُوا۟ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِىٓ أَصْحَـٰبِ ٱلسَّعِيرِ',562,29,57,225,1,7,496,0);
INSERT INTO "ayahs" VALUES(5252,67,11,'فَٱعْتَرَفُوا۟ بِذَنۢبِهِمْ فَسُحْقًا لِّأَصْحَـٰبِ ٱلسَّعِيرِ',562,29,57,225,1,7,496,0);
INSERT INTO "ayahs" VALUES(5253,67,12,'إِنَّ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ',562,29,57,225,1,7,496,0);
INSERT INTO "ayahs" VALUES(5254,67,13,'وَأَسِرُّوا۟ قَوْلَكُمْ أَوِ ٱجْهَرُوا۟ بِهِۦٓ ۖ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ',563,29,57,225,1,7,496,0);
INSERT INTO "ayahs" VALUES(5255,67,14,'أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ',563,29,57,225,1,7,496,0);
INSERT INTO "ayahs" VALUES(5256,67,15,'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ ذَلُولًا فَٱمْشُوا۟ فِى مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزْقِهِۦ ۖ وَإِلَيْهِ ٱلنُّشُورُ',563,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5257,67,16,'ءَأَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يَخْسِفَ بِكُمُ ٱلْأَرْضَ فَإِذَا هِىَ تَمُورُ',563,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5258,67,17,'أَمْ أَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًا ۖ فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ',563,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5259,67,18,'وَلَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ',563,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5260,67,19,'أَوَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ فَوْقَهُمْ صَـٰٓفَّـٰتٍ وَيَقْبِضْنَ ۚ مَا يُمْسِكُهُنَّ إِلَّا ٱلرَّحْمَـٰنُ ۚ إِنَّهُۥ بِكُلِّ شَىْءٍۭ بَصِيرٌ',563,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5261,67,20,'أَمَّنْ هَـٰذَا ٱلَّذِى هُوَ جُندٌ لَّكُمْ يَنصُرُكُم مِّن دُونِ ٱلرَّحْمَـٰنِ ۚ إِنِ ٱلْكَـٰفِرُونَ إِلَّا فِى غُرُورٍ',563,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5262,67,21,'أَمَّنْ هَـٰذَا ٱلَّذِى يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُۥ ۚ بَل لَّجُّوا۟ فِى عُتُوٍّ وَنُفُورٍ',563,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5263,67,22,'أَفَمَن يَمْشِى مُكِبًّا عَلَىٰ وَجْهِهِۦٓ أَهْدَىٰٓ أَمَّن يَمْشِى سَوِيًّا عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ',563,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5264,67,23,'قُلْ هُوَ ٱلَّذِىٓ أَنشَأَكُمْ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَـٰرَ وَٱلْأَفْـِٔدَةَ ۖ قَلِيلًا مَّا تَشْكُرُونَ',563,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5265,67,24,'قُلْ هُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ',563,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5266,67,25,'وَيَقُولُونَ مَتَىٰ هَـٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَـٰدِقِينَ',563,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5267,67,26,'قُلْ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ',563,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5268,67,27,'فَلَمَّا رَأَوْهُ زُلْفَةً سِيٓـَٔتْ وُجُوهُ ٱلَّذِينَ كَفَرُوا۟ وَقِيلَ هَـٰذَا ٱلَّذِى كُنتُم بِهِۦ تَدَّعُونَ',564,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5269,67,28,'قُلْ أَرَءَيْتُمْ إِنْ أَهْلَكَنِىَ ٱللَّهُ وَمَن مَّعِىَ أَوْ رَحِمَنَا فَمَن يُجِيرُ ٱلْكَـٰفِرِينَ مِنْ عَذَابٍ أَلِيمٍ',564,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5270,67,29,'قُلْ هُوَ ٱلرَّحْمَـٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا ۖ فَسَتَعْلَمُونَ مَنْ هُوَ فِى ضَلَـٰلٍ مُّبِينٍ',564,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5271,67,30,'قُلْ أَرَءَيْتُمْ إِنْ أَصْبَحَ مَآؤُكُمْ غَوْرًا فَمَن يَأْتِيكُم بِمَآءٍ مَّعِينٍۭ',564,29,57,225,1,7,497,0);
INSERT INTO "ayahs" VALUES(5272,68,1,'نٓ ۚ وَٱلْقَلَمِ وَمَا يَسْطُرُونَ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5273,68,2,'مَآ أَنتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5274,68,3,'وَإِنَّ لَكَ لَأَجْرًا غَيْرَ مَمْنُونٍ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5275,68,4,'وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5276,68,5,'فَسَتُبْصِرُ وَيُبْصِرُونَ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5277,68,6,'بِأَييِّكُمُ ٱلْمَفْتُونُ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5278,68,7,'إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5279,68,8,'فَلَا تُطِعِ ٱلْمُكَذِّبِينَ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5280,68,9,'وَدُّوا۟ لَوْ تُدْهِنُ فَيُدْهِنُونَ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5281,68,10,'وَلَا تُطِعْ كُلَّ حَلَّافٍ مَّهِينٍ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5282,68,11,'هَمَّازٍ مَّشَّآءٍۭ بِنَمِيمٍ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5283,68,12,'مَّنَّاعٍ لِّلْخَيْرِ مُعْتَدٍ أَثِيمٍ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5284,68,13,'عُتُلٍّۭ بَعْدَ ذَٰلِكَ زَنِيمٍ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5285,68,14,'أَن كَانَ ذَا مَالٍ وَبَنِينَ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5286,68,15,'إِذَا تُتْلَىٰ عَلَيْهِ ءَايَـٰتُنَا قَالَ أَسَـٰطِيرُ ٱلْأَوَّلِينَ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5287,68,16,'سَنَسِمُهُۥ عَلَى ٱلْخُرْطُومِ',564,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5288,68,17,'إِنَّا بَلَوْنَـٰهُمْ كَمَا بَلَوْنَآ أَصْحَـٰبَ ٱلْجَنَّةِ إِذْ أَقْسَمُوا۟ لَيَصْرِمُنَّهَا مُصْبِحِينَ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5289,68,18,'وَلَا يَسْتَثْنُونَ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5290,68,19,'فَطَافَ عَلَيْهَا طَآئِفٌ مِّن رَّبِّكَ وَهُمْ نَآئِمُونَ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5291,68,20,'فَأَصْبَحَتْ كَٱلصَّرِيمِ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5292,68,21,'فَتَنَادَوْا۟ مُصْبِحِينَ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5293,68,22,'أَنِ ٱغْدُوا۟ عَلَىٰ حَرْثِكُمْ إِن كُنتُمْ صَـٰرِمِينَ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5294,68,23,'فَٱنطَلَقُوا۟ وَهُمْ يَتَخَـٰفَتُونَ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5295,68,24,'أَن لَّا يَدْخُلَنَّهَا ٱلْيَوْمَ عَلَيْكُم مِّسْكِينٌ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5296,68,25,'وَغَدَوْا۟ عَلَىٰ حَرْدٍ قَـٰدِرِينَ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5297,68,26,'فَلَمَّا رَأَوْهَا قَالُوٓا۟ إِنَّا لَضَآلُّونَ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5298,68,27,'بَلْ نَحْنُ مَحْرُومُونَ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5299,68,28,'قَالَ أَوْسَطُهُمْ أَلَمْ أَقُل لَّكُمْ لَوْلَا تُسَبِّحُونَ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5300,68,29,'قَالُوا۟ سُبْحَـٰنَ رَبِّنَآ إِنَّا كُنَّا ظَـٰلِمِينَ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5301,68,30,'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَلَـٰوَمُونَ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5302,68,31,'قَالُوا۟ يَـٰوَيْلَنَآ إِنَّا كُنَّا طَـٰغِينَ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5303,68,32,'عَسَىٰ رَبُّنَآ أَن يُبْدِلَنَا خَيْرًا مِّنْهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5304,68,33,'كَذَٰلِكَ ٱلْعَذَابُ ۖ وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَكْبَرُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ',565,29,57,226,2,7,498,0);
INSERT INTO "ayahs" VALUES(5305,68,34,'إِنَّ لِلْمُتَّقِينَ عِندَ رَبِّهِمْ جَنَّـٰتِ ٱلنَّعِيمِ',565,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5306,68,35,'أَفَنَجْعَلُ ٱلْمُسْلِمِينَ كَٱلْمُجْرِمِينَ',565,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5307,68,36,'مَا لَكُمْ كَيْفَ تَحْكُمُونَ',565,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5308,68,37,'أَمْ لَكُمْ كِتَـٰبٌ فِيهِ تَدْرُسُونَ',565,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5309,68,38,'إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ',565,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5310,68,39,'أَمْ لَكُمْ أَيْمَـٰنٌ عَلَيْنَا بَـٰلِغَةٌ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ ۙ إِنَّ لَكُمْ لَمَا تَحْكُمُونَ',565,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5311,68,40,'سَلْهُمْ أَيُّهُم بِذَٰلِكَ زَعِيمٌ',565,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5312,68,41,'أَمْ لَهُمْ شُرَكَآءُ فَلْيَأْتُوا۟ بِشُرَكَآئِهِمْ إِن كَانُوا۟ صَـٰدِقِينَ',565,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5313,68,42,'يَوْمَ يُكْشَفُ عَن سَاقٍ وَيُدْعَوْنَ إِلَى ٱلسُّجُودِ فَلَا يَسْتَطِيعُونَ',565,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5314,68,43,'خَـٰشِعَةً أَبْصَـٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌ ۖ وَقَدْ كَانُوا۟ يُدْعَوْنَ إِلَى ٱلسُّجُودِ وَهُمْ سَـٰلِمُونَ',566,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5315,68,44,'فَذَرْنِى وَمَن يُكَذِّبُ بِهَـٰذَا ٱلْحَدِيثِ ۖ سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ',566,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5316,68,45,'وَأُمْلِى لَهُمْ ۚ إِنَّ كَيْدِى مَتِينٌ',566,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5317,68,46,'أَمْ تَسْـَٔلُهُمْ أَجْرًا فَهُم مِّن مَّغْرَمٍ مُّثْقَلُونَ',566,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5318,68,47,'أَمْ عِندَهُمُ ٱلْغَيْبُ فَهُمْ يَكْتُبُونَ',566,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5319,68,48,'فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلْحُوتِ إِذْ نَادَىٰ وَهُوَ مَكْظُومٌ',566,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5320,68,49,'لَّوْلَآ أَن تَدَٰرَكَهُۥ نِعْمَةٌ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلْعَرَآءِ وَهُوَ مَذْمُومٌ',566,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5321,68,50,'فَٱجْتَبَـٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّـٰلِحِينَ',566,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5322,68,51,'وَإِن يَكَادُ ٱلَّذِينَ كَفَرُوا۟ لَيُزْلِقُونَكَ بِأَبْصَـٰرِهِمْ لَمَّا سَمِعُوا۟ ٱلذِّكْرَ وَيَقُولُونَ إِنَّهُۥ لَمَجْنُونٌ',566,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5323,68,52,'وَمَا هُوَ إِلَّا ذِكْرٌ لِّلْعَـٰلَمِينَ',566,29,57,226,2,7,499,0);
INSERT INTO "ayahs" VALUES(5324,69,1,'ٱلْحَآقَّةُ',566,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5325,69,2,'مَا ٱلْحَآقَّةُ',566,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5326,69,3,'وَمَآ أَدْرَىٰكَ مَا ٱلْحَآقَّةُ',566,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5327,69,4,'كَذَّبَتْ ثَمُودُ وَعَادٌۢ بِٱلْقَارِعَةِ',566,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5328,69,5,'فَأَمَّا ثَمُودُ فَأُهْلِكُوا۟ بِٱلطَّاغِيَةِ',566,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5329,69,6,'وَأَمَّا عَادٌ فَأُهْلِكُوا۟ بِرِيحٍ صَرْصَرٍ عَاتِيَةٍ',566,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5330,69,7,'سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍ وَثَمَـٰنِيَةَ أَيَّامٍ حُسُومًا فَتَرَى ٱلْقَوْمَ فِيهَا صَرْعَىٰ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ خَاوِيَةٍ',566,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5331,69,8,'فَهَلْ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٍ',566,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5332,69,9,'وَجَآءَ فِرْعَوْنُ وَمَن قَبْلَهُۥ وَٱلْمُؤْتَفِكَـٰتُ بِٱلْخَاطِئَةِ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5333,69,10,'فَعَصَوْا۟ رَسُولَ رَبِّهِمْ فَأَخَذَهُمْ أَخْذَةً رَّابِيَةً',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5334,69,11,'إِنَّا لَمَّا طَغَا ٱلْمَآءُ حَمَلْنَـٰكُمْ فِى ٱلْجَارِيَةِ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5335,69,12,'لِنَجْعَلَهَا لَكُمْ تَذْكِرَةً وَتَعِيَهَآ أُذُنٌ وَٰعِيَةٌ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5336,69,13,'فَإِذَا نُفِخَ فِى ٱلصُّورِ نَفْخَةٌ وَٰحِدَةٌ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5337,69,14,'وَحُمِلَتِ ٱلْأَرْضُ وَٱلْجِبَالُ فَدُكَّتَا دَكَّةً وَٰحِدَةً',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5338,69,15,'فَيَوْمَئِذٍ وَقَعَتِ ٱلْوَاقِعَةُ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5339,69,16,'وَٱنشَقَّتِ ٱلسَّمَآءُ فَهِىَ يَوْمَئِذٍ وَاهِيَةٌ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5340,69,17,'وَٱلْمَلَكُ عَلَىٰٓ أَرْجَآئِهَا ۚ وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍ ثَمَـٰنِيَةٌ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5341,69,18,'يَوْمَئِذٍ تُعْرَضُونَ لَا تَخْفَىٰ مِنكُمْ خَافِيَةٌ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5342,69,19,'فَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ٱقْرَءُوا۟ كِتَـٰبِيَهْ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5343,69,20,'إِنِّى ظَنَنتُ أَنِّى مُلَـٰقٍ حِسَابِيَهْ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5344,69,21,'فَهُوَ فِى عِيشَةٍ رَّاضِيَةٍ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5345,69,22,'فِى جَنَّةٍ عَالِيَةٍ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5346,69,23,'قُطُوفُهَا دَانِيَةٌ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5347,69,24,'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَآ أَسْلَفْتُمْ فِى ٱلْأَيَّامِ ٱلْخَالِيَةِ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5348,69,25,'وَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ بِشِمَالِهِۦ فَيَقُولُ يَـٰلَيْتَنِى لَمْ أُوتَ كِتَـٰبِيَهْ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5349,69,26,'وَلَمْ أَدْرِ مَا حِسَابِيَهْ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5350,69,27,'يَـٰلَيْتَهَا كَانَتِ ٱلْقَاضِيَةَ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5351,69,28,'مَآ أَغْنَىٰ عَنِّى مَالِيَهْ ۜ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5352,69,29,'هَلَكَ عَنِّى سُلْطَـٰنِيَهْ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5353,69,30,'خُذُوهُ فَغُلُّوهُ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5354,69,31,'ثُمَّ ٱلْجَحِيمَ صَلُّوهُ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5355,69,32,'ثُمَّ فِى سِلْسِلَةٍ ذَرْعُهَا سَبْعُونَ ذِرَاعًا فَٱسْلُكُوهُ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5356,69,33,'إِنَّهُۥ كَانَ لَا يُؤْمِنُ بِٱللَّهِ ٱلْعَظِيمِ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5357,69,34,'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5358,69,35,'فَلَيْسَ لَهُ ٱلْيَوْمَ هَـٰهُنَا حَمِيمٌ',567,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5359,69,36,'وَلَا طَعَامٌ إِلَّا مِنْ غِسْلِينٍ',568,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5360,69,37,'لَّا يَأْكُلُهُۥٓ إِلَّا ٱلْخَـٰطِـُٔونَ',568,29,57,227,3,7,500,0);
INSERT INTO "ayahs" VALUES(5361,69,38,'فَلَآ أُقْسِمُ بِمَا تُبْصِرُونَ',568,29,57,227,3,7,501,0);
INSERT INTO "ayahs" VALUES(5362,69,39,'وَمَا لَا تُبْصِرُونَ',568,29,57,227,3,7,501,0);
INSERT INTO "ayahs" VALUES(5363,69,40,'إِنَّهُۥ لَقَوْلُ رَسُولٍ كَرِيمٍ',568,29,57,227,3,7,501,0);
INSERT INTO "ayahs" VALUES(5364,69,41,'وَمَا هُوَ بِقَوْلِ شَاعِرٍ ۚ قَلِيلًا مَّا تُؤْمِنُونَ',568,29,57,227,3,7,501,0);
INSERT INTO "ayahs" VALUES(5365,69,42,'وَلَا بِقَوْلِ كَاهِنٍ ۚ قَلِيلًا مَّا تَذَكَّرُونَ',568,29,57,227,3,7,501,0);
INSERT INTO "ayahs" VALUES(5366,69,43,'تَنزِيلٌ مِّن رَّبِّ ٱلْعَـٰلَمِينَ',568,29,57,227,3,7,501,0);
INSERT INTO "ayahs" VALUES(5367,69,44,'وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ ٱلْأَقَاوِيلِ',568,29,57,227,3,7,501,0);
INSERT INTO "ayahs" VALUES(5368,69,45,'لَأَخَذْنَا مِنْهُ بِٱلْيَمِينِ',568,29,57,227,3,7,501,0);
INSERT INTO "ayahs" VALUES(5369,69,46,'ثُمَّ لَقَطَعْنَا مِنْهُ ٱلْوَتِينَ',568,29,57,227,3,7,501,0);
INSERT INTO "ayahs" VALUES(5370,69,47,'فَمَا مِنكُم مِّنْ أَحَدٍ عَنْهُ حَـٰجِزِينَ',568,29,57,227,3,7,501,0);
INSERT INTO "ayahs" VALUES(5371,69,48,'وَإِنَّهُۥ لَتَذْكِرَةٌ لِّلْمُتَّقِينَ',568,29,57,227,3,7,501,0);
INSERT INTO "ayahs" VALUES(5372,69,49,'وَإِنَّا لَنَعْلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ',568,29,57,227,3,7,501,0);
INSERT INTO "ayahs" VALUES(5373,69,50,'وَإِنَّهُۥ لَحَسْرَةٌ عَلَى ٱلْكَـٰفِرِينَ',568,29,57,227,3,7,501,0);
INSERT INTO "ayahs" VALUES(5374,69,51,'وَإِنَّهُۥ لَحَقُّ ٱلْيَقِينِ',568,29,57,227,3,7,501,0);
INSERT INTO "ayahs" VALUES(5375,69,52,'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ',568,29,57,227,3,7,501,0);
INSERT INTO "ayahs" VALUES(5376,70,1,'سَأَلَ سَآئِلٌۢ بِعَذَابٍ وَاقِعٍ',568,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5377,70,2,'لِّلْكَـٰفِرِينَ لَيْسَ لَهُۥ دَافِعٌ',568,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5378,70,3,'مِّنَ ٱللَّهِ ذِى ٱلْمَعَارِجِ',568,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5379,70,4,'تَعْرُجُ ٱلْمَلَـٰٓئِكَةُ وَٱلرُّوحُ إِلَيْهِ فِى يَوْمٍ كَانَ مِقْدَارُهُۥ خَمْسِينَ أَلْفَ سَنَةٍ',568,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5380,70,5,'فَٱصْبِرْ صَبْرًا جَمِيلًا',568,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5381,70,6,'إِنَّهُمْ يَرَوْنَهُۥ بَعِيدًا',568,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5382,70,7,'وَنَرَىٰهُ قَرِيبًا',568,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5383,70,8,'يَوْمَ تَكُونُ ٱلسَّمَآءُ كَٱلْمُهْلِ',568,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5384,70,9,'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ',568,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5385,70,10,'وَلَا يَسْـَٔلُ حَمِيمٌ حَمِيمًا',568,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5386,70,11,'يُبَصَّرُونَهُمْ ۚ يَوَدُّ ٱلْمُجْرِمُ لَوْ يَفْتَدِى مِنْ عَذَابِ يَوْمِئِذٍۭ بِبَنِيهِ',569,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5387,70,12,'وَصَـٰحِبَتِهِۦ وَأَخِيهِ',569,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5388,70,13,'وَفَصِيلَتِهِ ٱلَّتِى تُـْٔوِيهِ',569,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5389,70,14,'وَمَن فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ يُنجِيهِ',569,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5390,70,15,'كَلَّآ ۖ إِنَّهَا لَظَىٰ',569,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5391,70,16,'نَزَّاعَةً لِّلشَّوَىٰ',569,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5392,70,17,'تَدْعُوا۟ مَنْ أَدْبَرَ وَتَوَلَّىٰ',569,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5393,70,18,'وَجَمَعَ فَأَوْعَىٰٓ',569,29,57,227,3,7,502,0);
INSERT INTO "ayahs" VALUES(5394,70,19,'۞ إِنَّ ٱلْإِنسَـٰنَ خُلِقَ هَلُوعًا',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5395,70,20,'إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعًا',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5396,70,21,'وَإِذَا مَسَّهُ ٱلْخَيْرُ مَنُوعًا',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5397,70,22,'إِلَّا ٱلْمُصَلِّينَ',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5398,70,23,'ٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَآئِمُونَ',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5399,70,24,'وَٱلَّذِينَ فِىٓ أَمْوَٰلِهِمْ حَقٌّ مَّعْلُومٌ',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5400,70,25,'لِّلسَّآئِلِ وَٱلْمَحْرُومِ',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5401,70,26,'وَٱلَّذِينَ يُصَدِّقُونَ بِيَوْمِ ٱلدِّينِ',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5402,70,27,'وَٱلَّذِينَ هُم مِّنْ عَذَابِ رَبِّهِم مُّشْفِقُونَ',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5403,70,28,'إِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَأْمُونٍ',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5404,70,29,'وَٱلَّذِينَ هُمْ لِفُرُوجِهِمْ حَـٰفِظُونَ',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5405,70,30,'إِلَّا عَلَىٰٓ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَـٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5406,70,31,'فَمَنِ ٱبْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْعَادُونَ',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5407,70,32,'وَٱلَّذِينَ هُمْ لِأَمَـٰنَـٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5408,70,33,'وَٱلَّذِينَ هُم بِشَهَـٰدَٰتِهِمْ قَآئِمُونَ',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5409,70,34,'وَٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5410,70,35,'أُو۟لَـٰٓئِكَ فِى جَنَّـٰتٍ مُّكْرَمُونَ',569,29,57,228,4,7,502,0);
INSERT INTO "ayahs" VALUES(5411,70,36,'فَمَالِ ٱلَّذِينَ كَفَرُوا۟ قِبَلَكَ مُهْطِعِينَ',569,29,57,228,4,7,503,0);
INSERT INTO "ayahs" VALUES(5412,70,37,'عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ عِزِينَ',569,29,57,228,4,7,503,0);
INSERT INTO "ayahs" VALUES(5413,70,38,'أَيَطْمَعُ كُلُّ ٱمْرِئٍ مِّنْهُمْ أَن يُدْخَلَ جَنَّةَ نَعِيمٍ',569,29,57,228,4,7,503,0);
INSERT INTO "ayahs" VALUES(5414,70,39,'كَلَّآ ۖ إِنَّا خَلَقْنَـٰهُم مِّمَّا يَعْلَمُونَ',569,29,57,228,4,7,503,0);
INSERT INTO "ayahs" VALUES(5415,70,40,'فَلَآ أُقْسِمُ بِرَبِّ ٱلْمَشَـٰرِقِ وَٱلْمَغَـٰرِبِ إِنَّا لَقَـٰدِرُونَ',569,29,57,228,4,7,503,0);
INSERT INTO "ayahs" VALUES(5416,70,41,'عَلَىٰٓ أَن نُّبَدِّلَ خَيْرًا مِّنْهُمْ وَمَا نَحْنُ بِمَسْبُوقِينَ',570,29,57,228,4,7,503,0);
INSERT INTO "ayahs" VALUES(5417,70,42,'فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَـٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ',570,29,57,228,4,7,503,0);
INSERT INTO "ayahs" VALUES(5418,70,43,'يَوْمَ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ سِرَاعًا كَأَنَّهُمْ إِلَىٰ نُصُبٍ يُوفِضُونَ',570,29,57,228,4,7,503,0);
INSERT INTO "ayahs" VALUES(5419,70,44,'خَـٰشِعَةً أَبْصَـٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌ ۚ ذَٰلِكَ ٱلْيَوْمُ ٱلَّذِى كَانُوا۟ يُوعَدُونَ',570,29,57,228,4,7,503,0);
INSERT INTO "ayahs" VALUES(5420,71,1,'إِنَّآ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ أَن يَأْتِيَهُمْ عَذَابٌ أَلِيمٌ',570,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5421,71,2,'قَالَ يَـٰقَوْمِ إِنِّى لَكُمْ نَذِيرٌ مُّبِينٌ',570,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5422,71,3,'أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ',570,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5423,71,4,'يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرْكُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى ۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُ ۖ لَوْ كُنتُمْ تَعْلَمُونَ',570,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5424,71,5,'قَالَ رَبِّ إِنِّى دَعَوْتُ قَوْمِى لَيْلًا وَنَهَارًا',570,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5425,71,6,'فَلَمْ يَزِدْهُمْ دُعَآءِىٓ إِلَّا فِرَارًا',570,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5426,71,7,'وَإِنِّى كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُوٓا۟ أَصَـٰبِعَهُمْ فِىٓ ءَاذَانِهِمْ وَٱسْتَغْشَوْا۟ ثِيَابَهُمْ وَأَصَرُّوا۟ وَٱسْتَكْبَرُوا۟ ٱسْتِكْبَارًا',570,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5427,71,8,'ثُمَّ إِنِّى دَعَوْتُهُمْ جِهَارًا',570,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5428,71,9,'ثُمَّ إِنِّىٓ أَعْلَنتُ لَهُمْ وَأَسْرَرْتُ لَهُمْ إِسْرَارًا',570,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5429,71,10,'فَقُلْتُ ٱسْتَغْفِرُوا۟ رَبَّكُمْ إِنَّهُۥ كَانَ غَفَّارًا',570,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5430,71,11,'يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا',571,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5431,71,12,'وَيُمْدِدْكُم بِأَمْوَٰلٍ وَبَنِينَ وَيَجْعَل لَّكُمْ جَنَّـٰتٍ وَيَجْعَل لَّكُمْ أَنْهَـٰرًا',571,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5432,71,13,'مَّا لَكُمْ لَا تَرْجُونَ لِلَّهِ وَقَارًا',571,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5433,71,14,'وَقَدْ خَلَقَكُمْ أَطْوَارًا',571,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5434,71,15,'أَلَمْ تَرَوْا۟ كَيْفَ خَلَقَ ٱللَّهُ سَبْعَ سَمَـٰوَٰتٍ طِبَاقًا',571,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5435,71,16,'وَجَعَلَ ٱلْقَمَرَ فِيهِنَّ نُورًا وَجَعَلَ ٱلشَّمْسَ سِرَاجًا',571,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5436,71,17,'وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلْأَرْضِ نَبَاتًا',571,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5437,71,18,'ثُمَّ يُعِيدُكُمْ فِيهَا وَيُخْرِجُكُمْ إِخْرَاجًا',571,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5438,71,19,'وَٱللَّهُ جَعَلَ لَكُمُ ٱلْأَرْضَ بِسَاطًا',571,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5439,71,20,'لِّتَسْلُكُوا۟ مِنْهَا سُبُلًا فِجَاجًا',571,29,57,228,4,7,504,0);
INSERT INTO "ayahs" VALUES(5440,71,21,'قَالَ نُوحٌ رَّبِّ إِنَّهُمْ عَصَوْنِى وَٱتَّبَعُوا۟ مَن لَّمْ يَزِدْهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارًا',571,29,57,228,4,7,505,0);
INSERT INTO "ayahs" VALUES(5441,71,22,'وَمَكَرُوا۟ مَكْرًا كُبَّارًا',571,29,57,228,4,7,505,0);
INSERT INTO "ayahs" VALUES(5442,71,23,'وَقَالُوا۟ لَا تَذَرُنَّ ءَالِهَتَكُمْ وَلَا تَذَرُنَّ وَدًّا وَلَا سُوَاعًا وَلَا يَغُوثَ وَيَعُوقَ وَنَسْرًا',571,29,57,228,4,7,505,0);
INSERT INTO "ayahs" VALUES(5443,71,24,'وَقَدْ أَضَلُّوا۟ كَثِيرًا ۖ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا ضَلَـٰلًا',571,29,57,228,4,7,505,0);
INSERT INTO "ayahs" VALUES(5444,71,25,'مِّمَّا خَطِيٓـَٔـٰتِهِمْ أُغْرِقُوا۟ فَأُدْخِلُوا۟ نَارًا فَلَمْ يَجِدُوا۟ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارًا',571,29,57,228,4,7,505,0);
INSERT INTO "ayahs" VALUES(5445,71,26,'وَقَالَ نُوحٌ رَّبِّ لَا تَذَرْ عَلَى ٱلْأَرْضِ مِنَ ٱلْكَـٰفِرِينَ دَيَّارًا',571,29,57,228,4,7,505,0);
INSERT INTO "ayahs" VALUES(5446,71,27,'إِنَّكَ إِن تَذَرْهُمْ يُضِلُّوا۟ عِبَادَكَ وَلَا يَلِدُوٓا۟ إِلَّا فَاجِرًا كَفَّارًا',571,29,57,228,4,7,505,0);
INSERT INTO "ayahs" VALUES(5447,71,28,'رَّبِّ ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا تَبَارًۢا',571,29,57,228,4,7,505,0);
INSERT INTO "ayahs" VALUES(5448,72,1,'قُلْ أُوحِىَ إِلَىَّ أَنَّهُ ٱسْتَمَعَ نَفَرٌ مِّنَ ٱلْجِنِّ فَقَالُوٓا۟ إِنَّا سَمِعْنَا قُرْءَانًا عَجَبًا',572,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5449,72,2,'يَهْدِىٓ إِلَى ٱلرُّشْدِ فَـَٔامَنَّا بِهِۦ ۖ وَلَن نُّشْرِكَ بِرَبِّنَآ أَحَدًا',572,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5450,72,3,'وَأَنَّهُۥ تَعَـٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَـٰحِبَةً وَلَا وَلَدًا',572,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5451,72,4,'وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطًا',572,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5452,72,5,'وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلْإِنسُ وَٱلْجِنُّ عَلَى ٱللَّهِ كَذِبًا',572,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5453,72,6,'وَأَنَّهُۥ كَانَ رِجَالٌ مِّنَ ٱلْإِنسِ يَعُوذُونَ بِرِجَالٍ مِّنَ ٱلْجِنِّ فَزَادُوهُمْ رَهَقًا',572,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5454,72,7,'وَأَنَّهُمْ ظَنُّوا۟ كَمَا ظَنَنتُمْ أَن لَّن يَبْعَثَ ٱللَّهُ أَحَدًا',572,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5455,72,8,'وَأَنَّا لَمَسْنَا ٱلسَّمَآءَ فَوَجَدْنَـٰهَا مُلِئَتْ حَرَسًا شَدِيدًا وَشُهُبًا',572,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5456,72,9,'وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَـٰعِدَ لِلسَّمْعِ ۖ فَمَن يَسْتَمِعِ ٱلْـَٔانَ يَجِدْ لَهُۥ شِهَابًا رَّصَدًا',572,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5457,72,10,'وَأَنَّا لَا نَدْرِىٓ أَشَرٌّ أُرِيدَ بِمَن فِى ٱلْأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا',572,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5458,72,11,'وَأَنَّا مِنَّا ٱلصَّـٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَ ۖ كُنَّا طَرَآئِقَ قِدَدًا',572,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5459,72,12,'وَأَنَّا ظَنَنَّآ أَن لَّن نُّعْجِزَ ٱللَّهَ فِى ٱلْأَرْضِ وَلَن نُّعْجِزَهُۥ هَرَبًا',572,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5460,72,13,'وَأَنَّا لَمَّا سَمِعْنَا ٱلْهُدَىٰٓ ءَامَنَّا بِهِۦ ۖ فَمَن يُؤْمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخْسًا وَلَا رَهَقًا',572,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5461,72,14,'وَأَنَّا مِنَّا ٱلْمُسْلِمُونَ وَمِنَّا ٱلْقَـٰسِطُونَ ۖ فَمَنْ أَسْلَمَ فَأُو۟لَـٰٓئِكَ تَحَرَّوْا۟ رَشَدًا',573,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5462,72,15,'وَأَمَّا ٱلْقَـٰسِطُونَ فَكَانُوا۟ لِجَهَنَّمَ حَطَبًا',573,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5463,72,16,'وَأَلَّوِ ٱسْتَقَـٰمُوا۟ عَلَى ٱلطَّرِيقَةِ لَأَسْقَيْنَـٰهُم مَّآءً غَدَقًا',573,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5464,72,17,'لِّنَفْتِنَهُمْ فِيهِ ۚ وَمَن يُعْرِضْ عَن ذِكْرِ رَبِّهِۦ يَسْلُكْهُ عَذَابًا صَعَدًا',573,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5465,72,18,'وَأَنَّ ٱلْمَسَـٰجِدَ لِلَّهِ فَلَا تَدْعُوا۟ مَعَ ٱللَّهِ أَحَدًا',573,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5466,72,19,'وَأَنَّهُۥ لَمَّا قَامَ عَبْدُ ٱللَّهِ يَدْعُوهُ كَادُوا۟ يَكُونُونَ عَلَيْهِ لِبَدًا',573,29,58,229,1,7,506,0);
INSERT INTO "ayahs" VALUES(5467,72,20,'قُلْ إِنَّمَآ أَدْعُوا۟ رَبِّى وَلَآ أُشْرِكُ بِهِۦٓ أَحَدًا',573,29,58,229,1,7,507,0);
INSERT INTO "ayahs" VALUES(5468,72,21,'قُلْ إِنِّى لَآ أَمْلِكُ لَكُمْ ضَرًّا وَلَا رَشَدًا',573,29,58,229,1,7,507,0);
INSERT INTO "ayahs" VALUES(5469,72,22,'قُلْ إِنِّى لَن يُجِيرَنِى مِنَ ٱللَّهِ أَحَدٌ وَلَنْ أَجِدَ مِن دُونِهِۦ مُلْتَحَدًا',573,29,58,229,1,7,507,0);
INSERT INTO "ayahs" VALUES(5470,72,23,'إِلَّا بَلَـٰغًا مِّنَ ٱللَّهِ وَرِسَـٰلَـٰتِهِۦ ۚ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَـٰلِدِينَ فِيهَآ أَبَدًا',573,29,58,229,1,7,507,0);
INSERT INTO "ayahs" VALUES(5471,72,24,'حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ أَضْعَفُ نَاصِرًا وَأَقَلُّ عَدَدًا',573,29,58,229,1,7,507,0);
INSERT INTO "ayahs" VALUES(5472,72,25,'قُلْ إِنْ أَدْرِىٓ أَقَرِيبٌ مَّا تُوعَدُونَ أَمْ يَجْعَلُ لَهُۥ رَبِّىٓ أَمَدًا',573,29,58,229,1,7,507,0);
INSERT INTO "ayahs" VALUES(5473,72,26,'عَـٰلِمُ ٱلْغَيْبِ فَلَا يُظْهِرُ عَلَىٰ غَيْبِهِۦٓ أَحَدًا',573,29,58,229,1,7,507,0);
INSERT INTO "ayahs" VALUES(5474,72,27,'إِلَّا مَنِ ٱرْتَضَىٰ مِن رَّسُولٍ فَإِنَّهُۥ يَسْلُكُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ رَصَدًا',573,29,58,229,1,7,507,0);
INSERT INTO "ayahs" VALUES(5475,72,28,'لِّيَعْلَمَ أَن قَدْ أَبْلَغُوا۟ رِسَـٰلَـٰتِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصَىٰ كُلَّ شَىْءٍ عَدَدًۢا',573,29,58,229,1,7,507,0);
INSERT INTO "ayahs" VALUES(5476,73,1,'يَـٰٓأَيُّهَا ٱلْمُزَّمِّلُ',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5477,73,2,'قُمِ ٱلَّيْلَ إِلَّا قَلِيلًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5478,73,3,'نِّصْفَهُۥٓ أَوِ ٱنقُصْ مِنْهُ قَلِيلًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5479,73,4,'أَوْ زِدْ عَلَيْهِ وَرَتِّلِ ٱلْقُرْءَانَ تَرْتِيلًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5480,73,5,'إِنَّا سَنُلْقِى عَلَيْكَ قَوْلًا ثَقِيلًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5481,73,6,'إِنَّ نَاشِئَةَ ٱلَّيْلِ هِىَ أَشَدُّ وَطْـًٔا وَأَقْوَمُ قِيلًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5482,73,7,'إِنَّ لَكَ فِى ٱلنَّهَارِ سَبْحًا طَوِيلًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5483,73,8,'وَٱذْكُرِ ٱسْمَ رَبِّكَ وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5484,73,9,'رَّبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ لَآ إِلَـٰهَ إِلَّا هُوَ فَٱتَّخِذْهُ وَكِيلًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5485,73,10,'وَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱهْجُرْهُمْ هَجْرًا جَمِيلًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5486,73,11,'وَذَرْنِى وَٱلْمُكَذِّبِينَ أُو۟لِى ٱلنَّعْمَةِ وَمَهِّلْهُمْ قَلِيلًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5487,73,12,'إِنَّ لَدَيْنَآ أَنكَالًا وَجَحِيمًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5488,73,13,'وَطَعَامًا ذَا غُصَّةٍ وَعَذَابًا أَلِيمًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5489,73,14,'يَوْمَ تَرْجُفُ ٱلْأَرْضُ وَٱلْجِبَالُ وَكَانَتِ ٱلْجِبَالُ كَثِيبًا مَّهِيلًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5490,73,15,'إِنَّآ أَرْسَلْنَآ إِلَيْكُمْ رَسُولًا شَـٰهِدًا عَلَيْكُمْ كَمَآ أَرْسَلْنَآ إِلَىٰ فِرْعَوْنَ رَسُولًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5491,73,16,'فَعَصَىٰ فِرْعَوْنُ ٱلرَّسُولَ فَأَخَذْنَـٰهُ أَخْذًا وَبِيلًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5492,73,17,'فَكَيْفَ تَتَّقُونَ إِن كَفَرْتُمْ يَوْمًا يَجْعَلُ ٱلْوِلْدَٰنَ شِيبًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5493,73,18,'ٱلسَّمَآءُ مُنفَطِرٌۢ بِهِۦ ۚ كَانَ وَعْدُهُۥ مَفْعُولًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5494,73,19,'إِنَّ هَـٰذِهِۦ تَذْكِرَةٌ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا',574,29,58,229,1,7,508,0);
INSERT INTO "ayahs" VALUES(5495,73,20,'۞ إِنَّ رَبَّكَ يَعْلَمُ أَنَّكَ تَقُومُ أَدْنَىٰ مِن ثُلُثَىِ ٱلَّيْلِ وَنِصْفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٌ مِّنَ ٱلَّذِينَ مَعَكَ ۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيْلَ وَٱلنَّهَارَ ۚ عَلِمَ أَن لَّن تُحْصُوهُ فَتَابَ عَلَيْكُمْ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنَ ٱلْقُرْءَانِ ۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرْضَىٰ ۙ وَءَاخَرُونَ يَضْرِبُونَ فِى ٱلْأَرْضِ يَبْتَغُونَ مِن فَضْلِ ٱللَّهِ ۙ وَءَاخَرُونَ يُقَـٰتِلُونَ فِى سَبِيلِ ٱللَّهِ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنْهُ ۚ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا ۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيْرًا وَأَعْظَمَ أَجْرًا ۚ وَٱسْتَغْفِرُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌۢ',575,29,58,230,2,7,509,0);
INSERT INTO "ayahs" VALUES(5496,74,1,'يَـٰٓأَيُّهَا ٱلْمُدَّثِّرُ',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5497,74,2,'قُمْ فَأَنذِرْ',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5498,74,3,'وَرَبَّكَ فَكَبِّرْ',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5499,74,4,'وَثِيَابَكَ فَطَهِّرْ',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5500,74,5,'وَٱلرُّجْزَ فَٱهْجُرْ',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5501,74,6,'وَلَا تَمْنُن تَسْتَكْثِرُ',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5502,74,7,'وَلِرَبِّكَ فَٱصْبِرْ',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5503,74,8,'فَإِذَا نُقِرَ فِى ٱلنَّاقُورِ',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5504,74,9,'فَذَٰلِكَ يَوْمَئِذٍ يَوْمٌ عَسِيرٌ',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5505,74,10,'عَلَى ٱلْكَـٰفِرِينَ غَيْرُ يَسِيرٍ',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5506,74,11,'ذَرْنِى وَمَنْ خَلَقْتُ وَحِيدًا',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5507,74,12,'وَجَعَلْتُ لَهُۥ مَالًا مَّمْدُودًا',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5508,74,13,'وَبَنِينَ شُهُودًا',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5509,74,14,'وَمَهَّدتُّ لَهُۥ تَمْهِيدًا',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5510,74,15,'ثُمَّ يَطْمَعُ أَنْ أَزِيدَ',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5511,74,16,'كَلَّآ ۖ إِنَّهُۥ كَانَ لِـَٔايَـٰتِنَا عَنِيدًا',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5512,74,17,'سَأُرْهِقُهُۥ صَعُودًا',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5513,74,18,'إِنَّهُۥ فَكَّرَ وَقَدَّرَ',575,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5514,74,19,'فَقُتِلَ كَيْفَ قَدَّرَ',576,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5515,74,20,'ثُمَّ قُتِلَ كَيْفَ قَدَّرَ',576,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5516,74,21,'ثُمَّ نَظَرَ',576,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5517,74,22,'ثُمَّ عَبَسَ وَبَسَرَ',576,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5518,74,23,'ثُمَّ أَدْبَرَ وَٱسْتَكْبَرَ',576,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5519,74,24,'فَقَالَ إِنْ هَـٰذَآ إِلَّا سِحْرٌ يُؤْثَرُ',576,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5520,74,25,'إِنْ هَـٰذَآ إِلَّا قَوْلُ ٱلْبَشَرِ',576,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5521,74,26,'سَأُصْلِيهِ سَقَرَ',576,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5522,74,27,'وَمَآ أَدْرَىٰكَ مَا سَقَرُ',576,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5523,74,28,'لَا تُبْقِى وَلَا تَذَرُ',576,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5524,74,29,'لَوَّاحَةٌ لِّلْبَشَرِ',576,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5525,74,30,'عَلَيْهَا تِسْعَةَ عَشَرَ',576,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5526,74,31,'وَمَا جَعَلْنَآ أَصْحَـٰبَ ٱلنَّارِ إِلَّا مَلَـٰٓئِكَةً ۙ وَمَا جَعَلْنَا عِدَّتَهُمْ إِلَّا فِتْنَةً لِّلَّذِينَ كَفَرُوا۟ لِيَسْتَيْقِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ وَيَزْدَادَ ٱلَّذِينَ ءَامَنُوٓا۟ إِيمَـٰنًا ۙ وَلَا يَرْتَابَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ وَٱلْمُؤْمِنُونَ ۙ وَلِيَقُولَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْكَـٰفِرُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلًا ۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ ۚ وَمَا هِىَ إِلَّا ذِكْرَىٰ لِلْبَشَرِ',576,29,58,230,2,7,510,0);
INSERT INTO "ayahs" VALUES(5527,74,32,'كَلَّا وَٱلْقَمَرِ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5528,74,33,'وَٱلَّيْلِ إِذْ أَدْبَرَ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5529,74,34,'وَٱلصُّبْحِ إِذَآ أَسْفَرَ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5530,74,35,'إِنَّهَا لَإِحْدَى ٱلْكُبَرِ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5531,74,36,'نَذِيرًا لِّلْبَشَرِ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5532,74,37,'لِمَن شَآءَ مِنكُمْ أَن يَتَقَدَّمَ أَوْ يَتَأَخَّرَ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5533,74,38,'كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ رَهِينَةٌ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5534,74,39,'إِلَّآ أَصْحَـٰبَ ٱلْيَمِينِ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5535,74,40,'فِى جَنَّـٰتٍ يَتَسَآءَلُونَ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5536,74,41,'عَنِ ٱلْمُجْرِمِينَ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5537,74,42,'مَا سَلَكَكُمْ فِى سَقَرَ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5538,74,43,'قَالُوا۟ لَمْ نَكُ مِنَ ٱلْمُصَلِّينَ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5539,74,44,'وَلَمْ نَكُ نُطْعِمُ ٱلْمِسْكِينَ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5540,74,45,'وَكُنَّا نَخُوضُ مَعَ ٱلْخَآئِضِينَ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5541,74,46,'وَكُنَّا نُكَذِّبُ بِيَوْمِ ٱلدِّينِ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5542,74,47,'حَتَّىٰٓ أَتَىٰنَا ٱلْيَقِينُ',576,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5543,74,48,'فَمَا تَنفَعُهُمْ شَفَـٰعَةُ ٱلشَّـٰفِعِينَ',577,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5544,74,49,'فَمَا لَهُمْ عَنِ ٱلتَّذْكِرَةِ مُعْرِضِينَ',577,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5545,74,50,'كَأَنَّهُمْ حُمُرٌ مُّسْتَنفِرَةٌ',577,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5546,74,51,'فَرَّتْ مِن قَسْوَرَةٍۭ',577,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5547,74,52,'بَلْ يُرِيدُ كُلُّ ٱمْرِئٍ مِّنْهُمْ أَن يُؤْتَىٰ صُحُفًا مُّنَشَّرَةً',577,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5548,74,53,'كَلَّا ۖ بَل لَّا يَخَافُونَ ٱلْـَٔاخِرَةَ',577,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5549,74,54,'كَلَّآ إِنَّهُۥ تَذْكِرَةٌ',577,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5550,74,55,'فَمَن شَآءَ ذَكَرَهُۥ',577,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5551,74,56,'وَمَا يَذْكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ هُوَ أَهْلُ ٱلتَّقْوَىٰ وَأَهْلُ ٱلْمَغْفِرَةِ',577,29,58,230,2,7,511,0);
INSERT INTO "ayahs" VALUES(5552,75,1,'لَآ أُقْسِمُ بِيَوْمِ ٱلْقِيَـٰمَةِ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5553,75,2,'وَلَآ أُقْسِمُ بِٱلنَّفْسِ ٱللَّوَّامَةِ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5554,75,3,'أَيَحْسَبُ ٱلْإِنسَـٰنُ أَلَّن نَّجْمَعَ عِظَامَهُۥ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5555,75,4,'بَلَىٰ قَـٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّىَ بَنَانَهُۥ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5556,75,5,'بَلْ يُرِيدُ ٱلْإِنسَـٰنُ لِيَفْجُرَ أَمَامَهُۥ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5557,75,6,'يَسْـَٔلُ أَيَّانَ يَوْمُ ٱلْقِيَـٰمَةِ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5558,75,7,'فَإِذَا بَرِقَ ٱلْبَصَرُ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5559,75,8,'وَخَسَفَ ٱلْقَمَرُ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5560,75,9,'وَجُمِعَ ٱلشَّمْسُ وَٱلْقَمَرُ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5561,75,10,'يَقُولُ ٱلْإِنسَـٰنُ يَوْمَئِذٍ أَيْنَ ٱلْمَفَرُّ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5562,75,11,'كَلَّا لَا وَزَرَ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5563,75,12,'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمُسْتَقَرُّ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5564,75,13,'يُنَبَّؤُا۟ ٱلْإِنسَـٰنُ يَوْمَئِذٍۭ بِمَا قَدَّمَ وَأَخَّرَ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5565,75,14,'بَلِ ٱلْإِنسَـٰنُ عَلَىٰ نَفْسِهِۦ بَصِيرَةٌ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5566,75,15,'وَلَوْ أَلْقَىٰ مَعَاذِيرَهُۥ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5567,75,16,'لَا تُحَرِّكْ بِهِۦ لِسَانَكَ لِتَعْجَلَ بِهِۦٓ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5568,75,17,'إِنَّ عَلَيْنَا جَمْعَهُۥ وَقُرْءَانَهُۥ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5569,75,18,'فَإِذَا قَرَأْنَـٰهُ فَٱتَّبِعْ قُرْءَانَهُۥ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5570,75,19,'ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُۥ',577,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5571,75,20,'كَلَّا بَلْ تُحِبُّونَ ٱلْعَاجِلَةَ',578,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5572,75,21,'وَتَذَرُونَ ٱلْـَٔاخِرَةَ',578,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5573,75,22,'وُجُوهٌ يَوْمَئِذٍ نَّاضِرَةٌ',578,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5574,75,23,'إِلَىٰ رَبِّهَا نَاظِرَةٌ',578,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5575,75,24,'وَوُجُوهٌ يَوْمَئِذٍۭ بَاسِرَةٌ',578,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5576,75,25,'تَظُنُّ أَن يُفْعَلَ بِهَا فَاقِرَةٌ',578,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5577,75,26,'كَلَّآ إِذَا بَلَغَتِ ٱلتَّرَاقِىَ',578,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5578,75,27,'وَقِيلَ مَنْ ۜ رَاقٍ',578,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5579,75,28,'وَظَنَّ أَنَّهُ ٱلْفِرَاقُ',578,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5580,75,29,'وَٱلْتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ',578,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5581,75,30,'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمَسَاقُ',578,29,58,231,3,7,512,0);
INSERT INTO "ayahs" VALUES(5582,75,31,'فَلَا صَدَّقَ وَلَا صَلَّىٰ',578,29,58,231,3,7,513,0);
INSERT INTO "ayahs" VALUES(5583,75,32,'وَلَـٰكِن كَذَّبَ وَتَوَلَّىٰ',578,29,58,231,3,7,513,0);
INSERT INTO "ayahs" VALUES(5584,75,33,'ثُمَّ ذَهَبَ إِلَىٰٓ أَهْلِهِۦ يَتَمَطَّىٰٓ',578,29,58,231,3,7,513,0);
INSERT INTO "ayahs" VALUES(5585,75,34,'أَوْلَىٰ لَكَ فَأَوْلَىٰ',578,29,58,231,3,7,513,0);
INSERT INTO "ayahs" VALUES(5586,75,35,'ثُمَّ أَوْلَىٰ لَكَ فَأَوْلَىٰٓ',578,29,58,231,3,7,513,0);
INSERT INTO "ayahs" VALUES(5587,75,36,'أَيَحْسَبُ ٱلْإِنسَـٰنُ أَن يُتْرَكَ سُدًى',578,29,58,231,3,7,513,0);
INSERT INTO "ayahs" VALUES(5588,75,37,'أَلَمْ يَكُ نُطْفَةً مِّن مَّنِىٍّ يُمْنَىٰ',578,29,58,231,3,7,513,0);
INSERT INTO "ayahs" VALUES(5589,75,38,'ثُمَّ كَانَ عَلَقَةً فَخَلَقَ فَسَوَّىٰ',578,29,58,231,3,7,513,0);
INSERT INTO "ayahs" VALUES(5590,75,39,'فَجَعَلَ مِنْهُ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ',578,29,58,231,3,7,513,0);
INSERT INTO "ayahs" VALUES(5591,75,40,'أَلَيْسَ ذَٰلِكَ بِقَـٰدِرٍ عَلَىٰٓ أَن يُحْـِۧىَ ٱلْمَوْتَىٰ',578,29,58,231,3,7,513,0);
INSERT INTO "ayahs" VALUES(5592,76,1,'هَلْ أَتَىٰ عَلَى ٱلْإِنسَـٰنِ حِينٌ مِّنَ ٱلدَّهْرِ لَمْ يَكُن شَيْـًٔا مَّذْكُورًا',578,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5593,76,2,'إِنَّا خَلَقْنَا ٱلْإِنسَـٰنَ مِن نُّطْفَةٍ أَمْشَاجٍ نَّبْتَلِيهِ فَجَعَلْنَـٰهُ سَمِيعًۢا بَصِيرًا',578,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5594,76,3,'إِنَّا هَدَيْنَـٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا',578,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5595,76,4,'إِنَّآ أَعْتَدْنَا لِلْكَـٰفِرِينَ سَلَـٰسِلَا۟ وَأَغْلَـٰلًا وَسَعِيرًا',578,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5596,76,5,'إِنَّ ٱلْأَبْرَارَ يَشْرَبُونَ مِن كَأْسٍ كَانَ مِزَاجُهَا كَافُورًا',578,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5597,76,6,'عَيْنًا يَشْرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفْجِيرًا',579,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5598,76,7,'يُوفُونَ بِٱلنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُۥ مُسْتَطِيرًا',579,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5599,76,8,'وَيُطْعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسْكِينًا وَيَتِيمًا وَأَسِيرًا',579,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5600,76,9,'إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ ٱللَّهِ لَا نُرِيدُ مِنكُمْ جَزَآءً وَلَا شُكُورًا',579,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5601,76,10,'إِنَّا نَخَافُ مِن رَّبِّنَا يَوْمًا عَبُوسًا قَمْطَرِيرًا',579,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5602,76,11,'فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلْيَوْمِ وَلَقَّىٰهُمْ نَضْرَةً وَسُرُورًا',579,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5603,76,12,'وَجَزَىٰهُم بِمَا صَبَرُوا۟ جَنَّةً وَحَرِيرًا',579,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5604,76,13,'مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ ۖ لَا يَرَوْنَ فِيهَا شَمْسًا وَلَا زَمْهَرِيرًا',579,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5605,76,14,'وَدَانِيَةً عَلَيْهِمْ ظِلَـٰلُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلًا',579,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5606,76,15,'وَيُطَافُ عَلَيْهِم بِـَٔانِيَةٍ مِّن فِضَّةٍ وَأَكْوَابٍ كَانَتْ قَوَارِيرَا۠',579,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5607,76,16,'قَوَارِيرَا۟ مِن فِضَّةٍ قَدَّرُوهَا تَقْدِيرًا',579,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5608,76,17,'وَيُسْقَوْنَ فِيهَا كَأْسًا كَانَ مِزَاجُهَا زَنجَبِيلًا',579,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5609,76,18,'عَيْنًا فِيهَا تُسَمَّىٰ سَلْسَبِيلًا',579,29,58,231,3,7,514,0);
INSERT INTO "ayahs" VALUES(5610,76,19,'۞ وَيَطُوفُ عَلَيْهِمْ وِلْدَٰنٌ مُّخَلَّدُونَ إِذَا رَأَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤًا مَّنثُورًا',579,29,58,232,4,7,514,0);
INSERT INTO "ayahs" VALUES(5611,76,20,'وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيمًا وَمُلْكًا كَبِيرًا',579,29,58,232,4,7,514,0);
INSERT INTO "ayahs" VALUES(5612,76,21,'عَـٰلِيَهُمْ ثِيَابُ سُندُسٍ خُضْرٌ وَإِسْتَبْرَقٌ ۖ وَحُلُّوٓا۟ أَسَاوِرَ مِن فِضَّةٍ وَسَقَىٰهُمْ رَبُّهُمْ شَرَابًا طَهُورًا',579,29,58,232,4,7,514,0);
INSERT INTO "ayahs" VALUES(5613,76,22,'إِنَّ هَـٰذَا كَانَ لَكُمْ جَزَآءً وَكَانَ سَعْيُكُم مَّشْكُورًا',579,29,58,232,4,7,514,0);
INSERT INTO "ayahs" VALUES(5614,76,23,'إِنَّا نَحْنُ نَزَّلْنَا عَلَيْكَ ٱلْقُرْءَانَ تَنزِيلًا',579,29,58,232,4,7,515,0);
INSERT INTO "ayahs" VALUES(5615,76,24,'فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمْ ءَاثِمًا أَوْ كَفُورًا',579,29,58,232,4,7,515,0);
INSERT INTO "ayahs" VALUES(5616,76,25,'وَٱذْكُرِ ٱسْمَ رَبِّكَ بُكْرَةً وَأَصِيلًا',579,29,58,232,4,7,515,0);
INSERT INTO "ayahs" VALUES(5617,76,26,'وَمِنَ ٱلَّيْلِ فَٱسْجُدْ لَهُۥ وَسَبِّحْهُ لَيْلًا طَوِيلًا',580,29,58,232,4,7,515,0);
INSERT INTO "ayahs" VALUES(5618,76,27,'إِنَّ هَـٰٓؤُلَآءِ يُحِبُّونَ ٱلْعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمْ يَوْمًا ثَقِيلًا',580,29,58,232,4,7,515,0);
INSERT INTO "ayahs" VALUES(5619,76,28,'نَّحْنُ خَلَقْنَـٰهُمْ وَشَدَدْنَآ أَسْرَهُمْ ۖ وَإِذَا شِئْنَا بَدَّلْنَآ أَمْثَـٰلَهُمْ تَبْدِيلًا',580,29,58,232,4,7,515,0);
INSERT INTO "ayahs" VALUES(5620,76,29,'إِنَّ هَـٰذِهِۦ تَذْكِرَةٌ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا',580,29,58,232,4,7,515,0);
INSERT INTO "ayahs" VALUES(5621,76,30,'وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا',580,29,58,232,4,7,515,0);
INSERT INTO "ayahs" VALUES(5622,76,31,'يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ ۚ وَٱلظَّـٰلِمِينَ أَعَدَّ لَهُمْ عَذَابًا أَلِيمًۢا',580,29,58,232,4,7,515,0);
INSERT INTO "ayahs" VALUES(5623,77,1,'وَٱلْمُرْسَلَـٰتِ عُرْفًا',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5624,77,2,'فَٱلْعَـٰصِفَـٰتِ عَصْفًا',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5625,77,3,'وَٱلنَّـٰشِرَٰتِ نَشْرًا',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5626,77,4,'فَٱلْفَـٰرِقَـٰتِ فَرْقًا',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5627,77,5,'فَٱلْمُلْقِيَـٰتِ ذِكْرًا',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5628,77,6,'عُذْرًا أَوْ نُذْرًا',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5629,77,7,'إِنَّمَا تُوعَدُونَ لَوَٰقِعٌ',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5630,77,8,'فَإِذَا ٱلنُّجُومُ طُمِسَتْ',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5631,77,9,'وَإِذَا ٱلسَّمَآءُ فُرِجَتْ',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5632,77,10,'وَإِذَا ٱلْجِبَالُ نُسِفَتْ',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5633,77,11,'وَإِذَا ٱلرُّسُلُ أُقِّتَتْ',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5634,77,12,'لِأَىِّ يَوْمٍ أُجِّلَتْ',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5635,77,13,'لِيَوْمِ ٱلْفَصْلِ',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5636,77,14,'وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلْفَصْلِ',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5637,77,15,'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5638,77,16,'أَلَمْ نُهْلِكِ ٱلْأَوَّلِينَ',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5639,77,17,'ثُمَّ نُتْبِعُهُمُ ٱلْـَٔاخِرِينَ',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5640,77,18,'كَذَٰلِكَ نَفْعَلُ بِٱلْمُجْرِمِينَ',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5641,77,19,'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ',580,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5642,77,20,'أَلَمْ نَخْلُقكُّم مِّن مَّآءٍ مَّهِينٍ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5643,77,21,'فَجَعَلْنَـٰهُ فِى قَرَارٍ مَّكِينٍ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5644,77,22,'إِلَىٰ قَدَرٍ مَّعْلُومٍ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5645,77,23,'فَقَدَرْنَا فَنِعْمَ ٱلْقَـٰدِرُونَ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5646,77,24,'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5647,77,25,'أَلَمْ نَجْعَلِ ٱلْأَرْضَ كِفَاتًا',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5648,77,26,'أَحْيَآءً وَأَمْوَٰتًا',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5649,77,27,'وَجَعَلْنَا فِيهَا رَوَٰسِىَ شَـٰمِخَـٰتٍ وَأَسْقَيْنَـٰكُم مَّآءً فُرَاتًا',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5650,77,28,'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5651,77,29,'ٱنطَلِقُوٓا۟ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5652,77,30,'ٱنطَلِقُوٓا۟ إِلَىٰ ظِلٍّ ذِى ثَلَـٰثِ شُعَبٍ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5653,77,31,'لَّا ظَلِيلٍ وَلَا يُغْنِى مِنَ ٱللَّهَبِ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5654,77,32,'إِنَّهَا تَرْمِى بِشَرَرٍ كَٱلْقَصْرِ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5655,77,33,'كَأَنَّهُۥ جِمَـٰلَتٌ صُفْرٌ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5656,77,34,'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5657,77,35,'هَـٰذَا يَوْمُ لَا يَنطِقُونَ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5658,77,36,'وَلَا يُؤْذَنُ لَهُمْ فَيَعْتَذِرُونَ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5659,77,37,'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5660,77,38,'هَـٰذَا يَوْمُ ٱلْفَصْلِ ۖ جَمَعْنَـٰكُمْ وَٱلْأَوَّلِينَ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5661,77,39,'فَإِن كَانَ لَكُمْ كَيْدٌ فَكِيدُونِ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5662,77,40,'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ',581,29,58,232,4,7,516,0);
INSERT INTO "ayahs" VALUES(5663,77,41,'إِنَّ ٱلْمُتَّقِينَ فِى ظِلَـٰلٍ وَعُيُونٍ',581,29,58,232,4,7,517,0);
INSERT INTO "ayahs" VALUES(5664,77,42,'وَفَوَٰكِهَ مِمَّا يَشْتَهُونَ',581,29,58,232,4,7,517,0);
INSERT INTO "ayahs" VALUES(5665,77,43,'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَا كُنتُمْ تَعْمَلُونَ',581,29,58,232,4,7,517,0);
INSERT INTO "ayahs" VALUES(5666,77,44,'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ',581,29,58,232,4,7,517,0);
INSERT INTO "ayahs" VALUES(5667,77,45,'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ',581,29,58,232,4,7,517,0);
INSERT INTO "ayahs" VALUES(5668,77,46,'كُلُوا۟ وَتَمَتَّعُوا۟ قَلِيلًا إِنَّكُم مُّجْرِمُونَ',581,29,58,232,4,7,517,0);
INSERT INTO "ayahs" VALUES(5669,77,47,'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ',581,29,58,232,4,7,517,0);
INSERT INTO "ayahs" VALUES(5670,77,48,'وَإِذَا قِيلَ لَهُمُ ٱرْكَعُوا۟ لَا يَرْكَعُونَ',581,29,58,232,4,7,517,0);
INSERT INTO "ayahs" VALUES(5671,77,49,'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ',581,29,58,232,4,7,517,0);
INSERT INTO "ayahs" VALUES(5672,77,50,'فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ',581,29,58,232,4,7,517,0);
INSERT INTO "ayahs" VALUES(5673,78,1,'عَمَّ يَتَسَآءَلُونَ',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5674,78,2,'عَنِ ٱلنَّبَإِ ٱلْعَظِيمِ',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5675,78,3,'ٱلَّذِى هُمْ فِيهِ مُخْتَلِفُونَ',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5676,78,4,'كَلَّا سَيَعْلَمُونَ',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5677,78,5,'ثُمَّ كَلَّا سَيَعْلَمُونَ',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5678,78,6,'أَلَمْ نَجْعَلِ ٱلْأَرْضَ مِهَـٰدًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5679,78,7,'وَٱلْجِبَالَ أَوْتَادًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5680,78,8,'وَخَلَقْنَـٰكُمْ أَزْوَٰجًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5681,78,9,'وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5682,78,10,'وَجَعَلْنَا ٱلَّيْلَ لِبَاسًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5683,78,11,'وَجَعَلْنَا ٱلنَّهَارَ مَعَاشًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5684,78,12,'وَبَنَيْنَا فَوْقَكُمْ سَبْعًا شِدَادًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5685,78,13,'وَجَعَلْنَا سِرَاجًا وَهَّاجًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5686,78,14,'وَأَنزَلْنَا مِنَ ٱلْمُعْصِرَٰتِ مَآءً ثَجَّاجًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5687,78,15,'لِّنُخْرِجَ بِهِۦ حَبًّا وَنَبَاتًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5688,78,16,'وَجَنَّـٰتٍ أَلْفَافًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5689,78,17,'إِنَّ يَوْمَ ٱلْفَصْلِ كَانَ مِيقَـٰتًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5690,78,18,'يَوْمَ يُنفَخُ فِى ٱلصُّورِ فَتَأْتُونَ أَفْوَاجًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5691,78,19,'وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتْ أَبْوَٰبًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5692,78,20,'وَسُيِّرَتِ ٱلْجِبَالُ فَكَانَتْ سَرَابًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5693,78,21,'إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5694,78,22,'لِّلطَّـٰغِينَ مَـَٔابًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5695,78,23,'لَّـٰبِثِينَ فِيهَآ أَحْقَابًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5696,78,24,'لَّا يَذُوقُونَ فِيهَا بَرْدًا وَلَا شَرَابًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5697,78,25,'إِلَّا حَمِيمًا وَغَسَّاقًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5698,78,26,'جَزَآءً وِفَاقًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5699,78,27,'إِنَّهُمْ كَانُوا۟ لَا يَرْجُونَ حِسَابًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5700,78,28,'وَكَذَّبُوا۟ بِـَٔايَـٰتِنَا كِذَّابًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5701,78,29,'وَكُلَّ شَىْءٍ أَحْصَيْنَـٰهُ كِتَـٰبًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5702,78,30,'فَذُوقُوا۟ فَلَن نَّزِيدَكُمْ إِلَّا عَذَابًا',582,30,59,233,1,7,518,0);
INSERT INTO "ayahs" VALUES(5703,78,31,'إِنَّ لِلْمُتَّقِينَ مَفَازًا',583,30,59,233,1,7,519,0);
INSERT INTO "ayahs" VALUES(5704,78,32,'حَدَآئِقَ وَأَعْنَـٰبًا',583,30,59,233,1,7,519,0);
INSERT INTO "ayahs" VALUES(5705,78,33,'وَكَوَاعِبَ أَتْرَابًا',583,30,59,233,1,7,519,0);
INSERT INTO "ayahs" VALUES(5706,78,34,'وَكَأْسًا دِهَاقًا',583,30,59,233,1,7,519,0);
INSERT INTO "ayahs" VALUES(5707,78,35,'لَّا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا كِذَّٰبًا',583,30,59,233,1,7,519,0);
INSERT INTO "ayahs" VALUES(5708,78,36,'جَزَآءً مِّن رَّبِّكَ عَطَآءً حِسَابًا',583,30,59,233,1,7,519,0);
INSERT INTO "ayahs" VALUES(5709,78,37,'رَّبِّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلرَّحْمَـٰنِ ۖ لَا يَمْلِكُونَ مِنْهُ خِطَابًا',583,30,59,233,1,7,519,0);
INSERT INTO "ayahs" VALUES(5710,78,38,'يَوْمَ يَقُومُ ٱلرُّوحُ وَٱلْمَلَـٰٓئِكَةُ صَفًّا ۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَـٰنُ وَقَالَ صَوَابًا',583,30,59,233,1,7,519,0);
INSERT INTO "ayahs" VALUES(5711,78,39,'ذَٰلِكَ ٱلْيَوْمُ ٱلْحَقُّ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا',583,30,59,233,1,7,519,0);
INSERT INTO "ayahs" VALUES(5712,78,40,'إِنَّآ أَنذَرْنَـٰكُمْ عَذَابًا قَرِيبًا يَوْمَ يَنظُرُ ٱلْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ ٱلْكَافِرُ يَـٰلَيْتَنِى كُنتُ تُرَٰبًۢا',583,30,59,233,1,7,519,0);
INSERT INTO "ayahs" VALUES(5713,79,1,'وَٱلنَّـٰزِعَـٰتِ غَرْقًا',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5714,79,2,'وَٱلنَّـٰشِطَـٰتِ نَشْطًا',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5715,79,3,'وَٱلسَّـٰبِحَـٰتِ سَبْحًا',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5716,79,4,'فَٱلسَّـٰبِقَـٰتِ سَبْقًا',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5717,79,5,'فَٱلْمُدَبِّرَٰتِ أَمْرًا',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5718,79,6,'يَوْمَ تَرْجُفُ ٱلرَّاجِفَةُ',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5719,79,7,'تَتْبَعُهَا ٱلرَّادِفَةُ',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5720,79,8,'قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5721,79,9,'أَبْصَـٰرُهَا خَـٰشِعَةٌ',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5722,79,10,'يَقُولُونَ أَءِنَّا لَمَرْدُودُونَ فِى ٱلْحَافِرَةِ',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5723,79,11,'أَءِذَا كُنَّا عِظَـٰمًا نَّخِرَةً',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5724,79,12,'قَالُوا۟ تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5725,79,13,'فَإِنَّمَا هِىَ زَجْرَةٌ وَٰحِدَةٌ',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5726,79,14,'فَإِذَا هُم بِٱلسَّاهِرَةِ',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5727,79,15,'هَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5728,79,16,'إِذْ نَادَىٰهُ رَبُّهُۥ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى',583,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5729,79,17,'ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ',584,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5730,79,18,'فَقُلْ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ',584,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5731,79,19,'وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ',584,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5732,79,20,'فَأَرَىٰهُ ٱلْـَٔايَةَ ٱلْكُبْرَىٰ',584,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5733,79,21,'فَكَذَّبَ وَعَصَىٰ',584,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5734,79,22,'ثُمَّ أَدْبَرَ يَسْعَىٰ',584,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5735,79,23,'فَحَشَرَ فَنَادَىٰ',584,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5736,79,24,'فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ',584,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5737,79,25,'فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلْـَٔاخِرَةِ وَٱلْأُولَىٰٓ',584,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5738,79,26,'إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّمَن يَخْشَىٰٓ',584,30,59,233,1,7,520,0);
INSERT INTO "ayahs" VALUES(5739,79,27,'ءَأَنتُمْ أَشَدُّ خَلْقًا أَمِ ٱلسَّمَآءُ ۚ بَنَىٰهَا',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5740,79,28,'رَفَعَ سَمْكَهَا فَسَوَّىٰهَا',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5741,79,29,'وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَىٰهَا',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5742,79,30,'وَٱلْأَرْضَ بَعْدَ ذَٰلِكَ دَحَىٰهَآ',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5743,79,31,'أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَىٰهَا',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5744,79,32,'وَٱلْجِبَالَ أَرْسَىٰهَا',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5745,79,33,'مَتَـٰعًا لَّكُمْ وَلِأَنْعَـٰمِكُمْ',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5746,79,34,'فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلْكُبْرَىٰ',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5747,79,35,'يَوْمَ يَتَذَكَّرُ ٱلْإِنسَـٰنُ مَا سَعَىٰ',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5748,79,36,'وَبُرِّزَتِ ٱلْجَحِيمُ لِمَن يَرَىٰ',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5749,79,37,'فَأَمَّا مَن طَغَىٰ',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5750,79,38,'وَءَاثَرَ ٱلْحَيَوٰةَ ٱلدُّنْيَا',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5751,79,39,'فَإِنَّ ٱلْجَحِيمَ هِىَ ٱلْمَأْوَىٰ',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5752,79,40,'وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5753,79,41,'فَإِنَّ ٱلْجَنَّةَ هِىَ ٱلْمَأْوَىٰ',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5754,79,42,'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5755,79,43,'فِيمَ أَنتَ مِن ذِكْرَىٰهَآ',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5756,79,44,'إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5757,79,45,'إِنَّمَآ أَنتَ مُنذِرُ مَن يَخْشَىٰهَا',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5758,79,46,'كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوٓا۟ إِلَّا عَشِيَّةً أَوْ ضُحَىٰهَا',584,30,59,233,1,7,521,0);
INSERT INTO "ayahs" VALUES(5759,80,1,'عَبَسَ وَتَوَلَّىٰٓ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5760,80,2,'أَن جَآءَهُ ٱلْأَعْمَىٰ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5761,80,3,'وَمَا يُدْرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5762,80,4,'أَوْ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكْرَىٰٓ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5763,80,5,'أَمَّا مَنِ ٱسْتَغْنَىٰ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5764,80,6,'فَأَنتَ لَهُۥ تَصَدَّىٰ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5765,80,7,'وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5766,80,8,'وَأَمَّا مَن جَآءَكَ يَسْعَىٰ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5767,80,9,'وَهُوَ يَخْشَىٰ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5768,80,10,'فَأَنتَ عَنْهُ تَلَهَّىٰ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5769,80,11,'كَلَّآ إِنَّهَا تَذْكِرَةٌ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5770,80,12,'فَمَن شَآءَ ذَكَرَهُۥ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5771,80,13,'فِى صُحُفٍ مُّكَرَّمَةٍ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5772,80,14,'مَّرْفُوعَةٍ مُّطَهَّرَةٍۭ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5773,80,15,'بِأَيْدِى سَفَرَةٍ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5774,80,16,'كِرَامٍۭ بَرَرَةٍ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5775,80,17,'قُتِلَ ٱلْإِنسَـٰنُ مَآ أَكْفَرَهُۥ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5776,80,18,'مِنْ أَىِّ شَىْءٍ خَلَقَهُۥ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5777,80,19,'مِن نُّطْفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5778,80,20,'ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5779,80,21,'ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5780,80,22,'ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5781,80,23,'كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5782,80,24,'فَلْيَنظُرِ ٱلْإِنسَـٰنُ إِلَىٰ طَعَامِهِۦٓ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5783,80,25,'أَنَّا صَبَبْنَا ٱلْمَآءَ صَبًّا',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5784,80,26,'ثُمَّ شَقَقْنَا ٱلْأَرْضَ شَقًّا',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5785,80,27,'فَأَنۢبَتْنَا فِيهَا حَبًّا',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5786,80,28,'وَعِنَبًا وَقَضْبًا',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5787,80,29,'وَزَيْتُونًا وَنَخْلًا',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5788,80,30,'وَحَدَآئِقَ غُلْبًا',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5789,80,31,'وَفَـٰكِهَةً وَأَبًّا',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5790,80,32,'مَّتَـٰعًا لَّكُمْ وَلِأَنْعَـٰمِكُمْ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5791,80,33,'فَإِذَا جَآءَتِ ٱلصَّآخَّةُ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5792,80,34,'يَوْمَ يَفِرُّ ٱلْمَرْءُ مِنْ أَخِيهِ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5793,80,35,'وَأُمِّهِۦ وَأَبِيهِ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5794,80,36,'وَصَـٰحِبَتِهِۦ وَبَنِيهِ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5795,80,37,'لِكُلِّ ٱمْرِئٍ مِّنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5796,80,38,'وُجُوهٌ يَوْمَئِذٍ مُّسْفِرَةٌ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5797,80,39,'ضَاحِكَةٌ مُّسْتَبْشِرَةٌ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5798,80,40,'وَوُجُوهٌ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌ',585,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5799,80,41,'تَرْهَقُهَا قَتَرَةٌ',586,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5800,80,42,'أُو۟لَـٰٓئِكَ هُمُ ٱلْكَفَرَةُ ٱلْفَجَرَةُ',586,30,59,234,2,7,522,0);
INSERT INTO "ayahs" VALUES(5801,81,1,'إِذَا ٱلشَّمْسُ كُوِّرَتْ',586,30,59,234,2,7,523,0);
INSERT INTO "ayahs" VALUES(5802,81,2,'وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتْ',586,30,59,234,2,7,523,0);
INSERT INTO "ayahs" VALUES(5803,81,3,'وَإِذَا ٱلْجِبَالُ سُيِّرَتْ',586,30,59,234,2,7,523,0);
INSERT INTO "ayahs" VALUES(5804,81,4,'وَإِذَا ٱلْعِشَارُ عُطِّلَتْ',586,30,59,234,2,7,523,0);
INSERT INTO "ayahs" VALUES(5805,81,5,'وَإِذَا ٱلْوُحُوشُ حُشِرَتْ',586,30,59,234,2,7,523,0);
INSERT INTO "ayahs" VALUES(5806,81,6,'وَإِذَا ٱلْبِحَارُ سُجِّرَتْ',586,30,59,234,2,7,523,0);
INSERT INTO "ayahs" VALUES(5807,81,7,'وَإِذَا ٱلنُّفُوسُ زُوِّجَتْ',586,30,59,234,2,7,523,0);
INSERT INTO "ayahs" VALUES(5808,81,8,'وَإِذَا ٱلْمَوْءُۥدَةُ سُئِلَتْ',586,30,59,234,2,7,523,0);
INSERT INTO "ayahs" VALUES(5809,81,9,'بِأَىِّ ذَنۢبٍ قُتِلَتْ',586,30,59,234,2,7,523,0);
INSERT INTO "ayahs" VALUES(5810,81,10,'وَإِذَا ٱلصُّحُفُ نُشِرَتْ',586,30,59,234,2,7,523,0);
INSERT INTO "ayahs" VALUES(5811,81,11,'وَإِذَا ٱلسَّمَآءُ كُشِطَتْ',586,30,59,234,2,7,523,0);
