INSERT INTO "ayahs" VALUES(6058,91,15,'وَلَا يَخَافُ عُقْبَـٰهَا',595,30,60,238,2,7,533,0);
INSERT INTO "ayahs" VALUES(6059,92,1,'وَٱلَّيْلِ إِذَا يَغْشَىٰ',595,30,60,238,2,7,534,0);
