INSERT INTO "ayahs" VALUES(6118,96,12,'أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ',597,30,60,239,3,7,538,0);
INSERT INTO "ayahs" VALUES(6119,96,13,'أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ',598,30,60,239,3,7,538,0);
INSERT INTO "ayahs" VALUES(6120,96,14,'أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ',598,30,60,239,3,7,538,0);
INSERT INTO "ayahs" VALUES(6121,96,15,'كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ',598,30,60,239,3,7,538,0);
INSERT INTO "ayahs" VALUES(6122,96,16,'نَاصِيَةٍ كَـٰذِبَةٍ خَاطِئَةٍ',598,30,60,239,3,7,538,0);
INSERT INTO "ayahs" VALUES(6123,96,17,'فَلْيَدْعُ نَادِيَهُۥ',598,30,60,239,3,7,538,0);
INSERT INTO "ayahs" VALUES(6124,96,18,'سَنَدْعُ ٱلزَّبَانِيَةَ',598,30,60,239,3,7,538,0);
INSERT INTO "ayahs" VALUES(6125,96,19,'كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب ۩',598,30,60,239,3,7,538,1);
INSERT INTO "ayahs" VALUES(6126,97,1,'إِنَّآ أَنزَلْنَـٰهُ فِى لَيْلَةِ ٱلْقَدْرِ',598,30,60,239,3,7,539,0);
INSERT INTO "ayahs" VALUES(6127,97,2,'وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ',598,30,60,239,3,7,539,0);
INSERT INTO "ayahs" VALUES(6128,97,3,'لَيْلَةُ ٱلْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ',598,30,60,239,3,7,539,0);
INSERT INTO "ayahs" VALUES(6129,97,4,'تَنَزَّلُ ٱلْمَلَـٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ',598,30,60,239,3,7,539,0);
INSERT INTO "ayahs" VALUES(6130,97,5,'سَلَـٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ',598,30,60,239,3,7,539,0);
INSERT INTO "ayahs" VALUES(6131,98,1,'لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ',598,30,60,239,3,7,540,0);
INSERT INTO "ayahs" VALUES(6132,98,2,'رَسُولٌ مِّنَ ٱللَّهِ يَتْلُوا۟ صُحُفًا مُّطَهَّرَةً',598,30,60,239,3,7,540,0);
INSERT INTO "ayahs" VALUES(6133,98,3,'فِيهَا كُتُبٌ قَيِّمَةٌ',598,30,60,239,3,7,540,0);
INSERT INTO "ayahs" VALUES(6134,98,4,'وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ',598,30,60,239,3,7,540,0);
INSERT INTO "ayahs" VALUES(6135,98,5,'وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ',598,30,60,239,3,7,540,0);
INSERT INTO "ayahs" VALUES(6136,98,6,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَـٰلِدِينَ فِيهَآ ۚ أُو۟لَـٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ',599,30,60,239,3,7,540,0);
INSERT INTO "ayahs" VALUES(6137,98,7,'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ',599,30,60,239,3,7,540,0);
INSERT INTO "ayahs" VALUES(6138,98,8,'جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّـٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۖ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ',599,30,60,239,3,7,540,0);
INSERT INTO "ayahs" VALUES(6139,99,1,'إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا',599,30,60,239,3,7,541,0);
INSERT INTO "ayahs" VALUES(6140,99,2,'وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا',599,30,60,239,3,7,541,0);
INSERT INTO "ayahs" VALUES(6141,99,3,'وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا',599,30,60,239,3,7,541,0);
INSERT INTO "ayahs" VALUES(6142,99,4,'يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا',599,30,60,239,3,7,541,0);
INSERT INTO "ayahs" VALUES(6143,99,5,'بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا',599,30,60,239,3,7,541,0);
INSERT INTO "ayahs" VALUES(6144,99,6,'يَوْمَئِذٍ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًا لِّيُرَوْا۟ أَعْمَـٰلَهُمْ',599,30,60,239,3,7,541,0);
INSERT INTO "ayahs" VALUES(6145,99,7,'فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُۥ',599,30,60,239,3,7,541,0);
INSERT INTO "ayahs" VALUES(6146,99,8,'وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ',599,30,60,239,3,7,541,0);
INSERT INTO "ayahs" VALUES(6147,100,1,'وَٱلْعَـٰدِيَـٰتِ ضَبْحًا',599,30,60,239,3,7,542,0);
INSERT INTO "ayahs" VALUES(6148,100,2,'فَٱلْمُورِيَـٰتِ قَدْحًا',599,30,60,239,3,7,542,0);
INSERT INTO "ayahs" VALUES(6149,100,3,'فَٱلْمُغِيرَٰتِ صُبْحًا',599,30,60,239,3,7,542,0);
INSERT INTO "ayahs" VALUES(6150,100,4,'فَأَثَرْنَ بِهِۦ نَقْعًا',599,30,60,239,3,7,542,0);
INSERT INTO "ayahs" VALUES(6151,100,5,'فَوَسَطْنَ بِهِۦ جَمْعًا',599,30,60,239,3,7,542,0);
INSERT INTO "ayahs" VALUES(6152,100,6,'إِنَّ ٱلْإِنسَـٰنَ لِرَبِّهِۦ لَكَنُودٌ',600,30,60,239,3,7,542,0);
INSERT INTO "ayahs" VALUES(6153,100,7,'وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌ',600,30,60,239,3,7,542,0);
INSERT INTO "ayahs" VALUES(6154,100,8,'وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ',600,30,60,239,3,7,542,0);
INSERT INTO "ayahs" VALUES(6155,100,9,'۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ',600,30,60,240,4,7,542,0);
INSERT INTO "ayahs" VALUES(6156,100,10,'وَحُصِّلَ مَا فِى ٱلصُّدُورِ',600,30,60,240,4,7,542,0);
INSERT INTO "ayahs" VALUES(6157,100,11,'إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍ لَّخَبِيرٌۢ',600,30,60,240,4,7,542,0);
INSERT INTO "ayahs" VALUES(6158,101,1,'ٱلْقَارِعَةُ',600,30,60,240,4,7,543,0);
INSERT INTO "ayahs" VALUES(6159,101,2,'مَا ٱلْقَارِعَةُ',600,30,60,240,4,7,543,0);
INSERT INTO "ayahs" VALUES(6160,101,3,'وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ',600,30,60,240,4,7,543,0);
INSERT INTO "ayahs" VALUES(6161,101,4,'يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ',600,30,60,240,4,7,543,0);
INSERT INTO "ayahs" VALUES(6162,101,5,'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ',600,30,60,240,4,7,543,0);
INSERT INTO "ayahs" VALUES(6163,101,6,'فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ',600,30,60,240,4,7,543,0);
INSERT INTO "ayahs" VALUES(6164,101,7,'فَهُوَ فِى عِيشَةٍ رَّاضِيَةٍ',600,30,60,240,4,7,543,0);
INSERT INTO "ayahs" VALUES(6165,101,8,'وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ',600,30,60,240,4,7,543,0);
INSERT INTO "ayahs" VALUES(6166,101,9,'فَأُمُّهُۥ هَاوِيَةٌ',600,30,60,240,4,7,543,0);
INSERT INTO "ayahs" VALUES(6167,101,10,'وَمَآ أَدْرَىٰكَ مَا هِيَهْ',600,30,60,240,4,7,543,0);
INSERT INTO "ayahs" VALUES(6168,101,11,'نَارٌ حَامِيَةٌۢ',600,30,60,240,4,7,543,0);
INSERT INTO "ayahs" VALUES(6169,102,1,'أَلْهَىٰكُمُ ٱلتَّكَاثُرُ',600,30,60,240,4,7,544,0);
INSERT INTO "ayahs" VALUES(6170,102,2,'حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ',600,30,60,240,4,7,544,0);
INSERT INTO "ayahs" VALUES(6171,102,3,'كَلَّا سَوْفَ تَعْلَمُونَ',600,30,60,240,4,7,544,0);
INSERT INTO "ayahs" VALUES(6172,102,4,'ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ',600,30,60,240,4,7,544,0);
INSERT INTO "ayahs" VALUES(6173,102,5,'كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ',600,30,60,240,4,7,544,0);
INSERT INTO "ayahs" VALUES(6174,102,6,'لَتَرَوُنَّ ٱلْجَحِيمَ',600,30,60,240,4,7,544,0);
INSERT INTO "ayahs" VALUES(6175,102,7,'ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ',600,30,60,240,4,7,544,0);
INSERT INTO "ayahs" VALUES(6176,102,8,'ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ',600,30,60,240,4,7,544,0);
INSERT INTO "ayahs" VALUES(6177,103,1,'وَٱلْعَصْرِ',601,30,60,240,4,7,545,0);
INSERT INTO "ayahs" VALUES(6178,103,2,'إِنَّ ٱلْإِنسَـٰنَ لَفِى خُسْرٍ',601,30,60,240,4,7,545,0);
INSERT INTO "ayahs" VALUES(6179,103,3,'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ',601,30,60,240,4,7,545,0);
INSERT INTO "ayahs" VALUES(6180,104,1,'وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ',601,30,60,240,4,7,546,0);
INSERT INTO "ayahs" VALUES(6181,104,2,'ٱلَّذِى جَمَعَ مَالًا وَعَدَّدَهُۥ',601,30,60,240,4,7,546,0);
INSERT INTO "ayahs" VALUES(6182,104,3,'يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ',601,30,60,240,4,7,546,0);
INSERT INTO "ayahs" VALUES(6183,104,4,'كَلَّا ۖ لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ',601,30,60,240,4,7,546,0);
INSERT INTO "ayahs" VALUES(6184,104,5,'وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ',601,30,60,240,4,7,546,0);
INSERT INTO "ayahs" VALUES(6185,104,6,'نَارُ ٱللَّهِ ٱلْمُوقَدَةُ',601,30,60,240,4,7,546,0);
INSERT INTO "ayahs" VALUES(6186,104,7,'ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ',601,30,60,240,4,7,546,0);
INSERT INTO "ayahs" VALUES(6187,104,8,'إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌ',601,30,60,240,4,7,546,0);
INSERT INTO "ayahs" VALUES(6188,104,9,'فِى عَمَدٍ مُّمَدَّدَةٍۭ',601,30,60,240,4,7,546,0);
INSERT INTO "ayahs" VALUES(6189,105,1,'أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَـٰبِ ٱلْفِيلِ',601,30,60,240,4,7,547,0);
INSERT INTO "ayahs" VALUES(6190,105,2,'أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍ',601,30,60,240,4,7,547,0);
INSERT INTO "ayahs" VALUES(6191,105,3,'وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ',601,30,60,240,4,7,547,0);
INSERT INTO "ayahs" VALUES(6192,105,4,'تَرْمِيهِم بِحِجَارَةٍ مِّن سِجِّيلٍ',601,30,60,240,4,7,547,0);
INSERT INTO "ayahs" VALUES(6193,105,5,'فَجَعَلَهُمْ كَعَصْفٍ مَّأْكُولٍۭ',601,30,60,240,4,7,547,0);
INSERT INTO "ayahs" VALUES(6194,106,1,'لِإِيلَـٰفِ قُرَيْشٍ',602,30,60,240,4,7,548,0);
INSERT INTO "ayahs" VALUES(6195,106,2,'إِۦلَـٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ',602,30,60,240,4,7,548,0);
INSERT INTO "ayahs" VALUES(6196,106,3,'فَلْيَعْبُدُوا۟ رَبَّ هَـٰذَا ٱلْبَيْتِ',602,30,60,240,4,7,548,0);
INSERT INTO "ayahs" VALUES(6197,106,4,'ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍ وَءَامَنَهُم مِّنْ خَوْفٍۭ',602,30,60,240,4,7,548,0);
INSERT INTO "ayahs" VALUES(6198,107,1,'أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ',602,30,60,240,4,7,549,0);
INSERT INTO "ayahs" VALUES(6199,107,2,'فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ',602,30,60,240,4,7,549,0);
INSERT INTO "ayahs" VALUES(6200,107,3,'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ',602,30,60,240,4,7,549,0);
INSERT INTO "ayahs" VALUES(6201,107,4,'فَوَيْلٌ لِّلْمُصَلِّينَ',602,30,60,240,4,7,549,0);
INSERT INTO "ayahs" VALUES(6202,107,5,'ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ',602,30,60,240,4,7,549,0);
INSERT INTO "ayahs" VALUES(6203,107,6,'ٱلَّذِينَ هُمْ يُرَآءُونَ',602,30,60,240,4,7,549,0);
INSERT INTO "ayahs" VALUES(6204,107,7,'وَيَمْنَعُونَ ٱلْمَاعُونَ',602,30,60,240,4,7,549,0);
INSERT INTO "ayahs" VALUES(6205,108,1,'إِنَّآ أَعْطَيْنَـٰكَ ٱلْكَوْثَرَ',602,30,60,240,4,7,550,0);
INSERT INTO "ayahs" VALUES(6206,108,2,'فَصَلِّ لِرَبِّكَ وَٱنْحَرْ',602,30,60,240,4,7,550,0);
INSERT INTO "ayahs" VALUES(6207,108,3,'إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ',602,30,60,240,4,7,550,0);
INSERT INTO "ayahs" VALUES(6208,109,1,'قُلْ يَـٰٓأَيُّهَا ٱلْكَـٰفِرُونَ',603,30,60,240,4,7,551,0);
INSERT INTO "ayahs" VALUES(6209,109,2,'لَآ أَعْبُدُ مَا تَعْبُدُونَ',603,30,60,240,4,7,551,0);
INSERT INTO "ayahs" VALUES(6210,109,3,'وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ',603,30,60,240,4,7,551,0);
INSERT INTO "ayahs" VALUES(6211,109,4,'وَلَآ أَنَا۠ عَابِدٌ مَّا عَبَدتُّمْ',603,30,60,240,4,7,551,0);
INSERT INTO "ayahs" VALUES(6212,109,5,'وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ',603,30,60,240,4,7,551,0);
INSERT INTO "ayahs" VALUES(6213,109,6,'لَكُمْ دِينُكُمْ وَلِىَ دِينِ',603,30,60,240,4,7,551,0);
INSERT INTO "ayahs" VALUES(6214,110,1,'إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ',603,30,60,240,4,7,552,0);
INSERT INTO "ayahs" VALUES(6215,110,2,'وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًا',603,30,60,240,4,7,552,0);
INSERT INTO "ayahs" VALUES(6216,110,3,'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا',603,30,60,240,4,7,552,0);
INSERT INTO "ayahs" VALUES(6217,111,1,'تَبَّتْ يَدَآ أَبِى لَهَبٍ وَتَبَّ',603,30,60,240,4,7,553,0);
INSERT INTO "ayahs" VALUES(6218,111,2,'مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ',603,30,60,240,4,7,553,0);
INSERT INTO "ayahs" VALUES(6219,111,3,'سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ',603,30,60,240,4,7,553,0);
INSERT INTO "ayahs" VALUES(6220,111,4,'وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ',603,30,60,240,4,7,553,0);
INSERT INTO "ayahs" VALUES(6221,111,5,'فِى جِيدِهَا حَبْلٌ مِّن مَّسَدٍۭ',603,30,60,240,4,7,553,0);
INSERT INTO "ayahs" VALUES(6222,112,1,'قُلْ هُوَ ٱللَّهُ أَحَدٌ',604,30,60,240,4,7,554,0);
INSERT INTO "ayahs" VALUES(6223,112,2,'ٱللَّهُ ٱلصَّمَدُ',604,30,60,240,4,7,554,0);
INSERT INTO "ayahs" VALUES(6224,112,3,'لَمْ يَلِدْ وَلَمْ يُولَدْ',604,30,60,240,4,7,554,0);
INSERT INTO "ayahs" VALUES(6225,112,4,'وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ',604,30,60,240,4,7,554,0);
INSERT INTO "ayahs" VALUES(6226,113,1,'قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ',604,30,60,240,4,7,555,0);
INSERT INTO "ayahs" VALUES(6227,113,2,'مِن شَرِّ مَا خَلَقَ',604,30,60,240,4,7,555,0);
INSERT INTO "ayahs" VALUES(6228,113,3,'وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ',604,30,60,240,4,7,555,0);
INSERT INTO "ayahs" VALUES(6229,113,4,'وَمِن شَرِّ ٱلنَّفَّـٰثَـٰتِ فِى ٱلْعُقَدِ',604,30,60,240,4,7,555,0);
INSERT INTO "ayahs" VALUES(6230,113,5,'وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ',604,30,60,240,4,7,555,0);
INSERT INTO "ayahs" VALUES(6231,114,1,'قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ',604,30,60,240,4,7,556,0);
INSERT INTO "ayahs" VALUES(6232,114,2,'مَلِكِ ٱلنَّاسِ',604,30,60,240,4,7,556,0);
INSERT INTO "ayahs" VALUES(6233,114,3,'إِلَـٰهِ ٱلنَّاسِ',604,30,60,240,4,7,556,0);
INSERT INTO "ayahs" VALUES(6234,114,4,'مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ',604,30,60,240,4,7,556,0);
INSERT INTO "ayahs" VALUES(6235,114,5,'ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ',604,30,60,240,4,7,556,0);
INSERT INTO "ayahs" VALUES(6236,114,6,'مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ',604,30,60,240,4,7,556,0);
